  );

  const deleteRepresentative = useCallback(
    async (partyId: string, representativeId: string) => {
      try {
        // Implementation will be added when we integrate with the API
      } catch (error) {
        console.error("Failed to delete representative:", error);
      }
    },
    []
  );

  const value: PartiesContextType = {
    // State
    parties,
    selectedParty,
    concerns,
    loading,
    searchTerm,
    partyTypeFilter,

    // Actions
    setSelectedParty,
    createParty,
    updateParty,
    deleteParty,
    addRepresentative,
    deleteRepresentative,
    createConcern,
    deleteConcern,

    // Filters and search
    setSearchTerm,
    setPartyTypeFilter,

    // Computed values
    filteredParties: sortedParties,
    organizationCount,
    individualCount,
    hasSearchResults: hasResults,
  };

  return (
    <PartiesContext.Provider value={value}>{children}</PartiesContext.Provider>
  );
};

export const usePartiesContext = () => {
  const context = useContext(PartiesContext);
  if (context === undefined) {
    throw new Error("usePartiesContext must be used within a PartiesProvider");
  }
  return context;
};

// Helper hooks for specific functionality
export const usePartyOperations = () => {
  const { createParty, updateParty, deleteParty } = usePartiesContext();
  return { createParty, updateParty, deleteParty };
};

export const useRepresentativeOperations = () => {
  const { addRepresentative, deleteRepresentative } = usePartiesContext();
  return { addRepresentative, deleteRepresentative };
};

export const useConcernOperations = () => {
  const { createConcern, deleteConcern } = usePartiesContext();
  return { createConcern, deleteConcern };
};

export const usePartyFilters = () => {
  const {
    searchTerm,
    setSearchTerm,
    partyTypeFilter,
    setPartyTypeFilter,
    filteredParties,
    organizationCount,
    individualCount,
    hasSearchResults,
  } = usePartiesContext();

  return {
    searchTerm,
    setSearchTerm,
    partyTypeFilter,
    setPartyTypeFilter,
    filteredParties,
    organizationCount,
    individualCount,
    hasSearchResults,
  };
};

import { useState, useEffect, useCallback } from "react";
import { api } from "@/services/api";
import { joinApiUrl } from "@/config/api";
import { authenticatedFetch } from "@/services/http";

export type LetterStatus =
  | "Draft"
  | "Input"
  | "Review"
  | "Approval"
  | "Completed"
  | "Rejected";

export interface User {
  id: string;
  name: string;
  email: string;
  avatar?: string;
  // Optional fields used for permission/org scoping
  roles?: string[];
  organizationId?: string | null;
  projects?: string[];
}

export interface Organization {
  id: string;
  name: string;
  description?: string;
}

export interface Project {
  id: string;
  name: string;
  description?: string;
  organizationId: string;
}

export interface LetterRef {
  id: string;
  title: string;
  subject: string;
  date: string;
  reference_number: string;
}

export interface Letter {
  id: string;
  title: string;
  recipient: string;
  subject: string;
  content: string;
  status: LetterStatus;
  created_by: string;
  assigned_to: string;
  organization_id: string;
  project_id?: string;
  created_at: string;
  updated_at: string;
  due_date?: string;
  comments: string[];
  reference?: LetterRef | null;
  status_start_date?: string;
  statusStartDate?: string;
  pendency_days?: number;
  pendencyDays?: number;
}

export interface CreateLetterInput {
  title: string;
  recipient: string;
  subject: string;
  content?: string;
  assigned_to: string;
  organization_id?: string;
  project_id?: string;
  reference?: LetterRef | null;
  due_date?: string | null;
  useAI?: boolean;
  context?: string;
}

export interface InputRequest {
  id: string;
  letter_id: string;
  requested_from: string;
  details: string;
  due_date?: string;
  status: string;
  response?: string;
  created_at: string;
  updated_at: string;
}

export const useLetterWorkflow = () => {
  const [activeTab, setActiveTab] = useState<LetterStatus | "All">("All");
  const [isInitiateDialogOpen, setIsInitiateDialogOpen] = useState(false);
  const [isRequestInputDialogOpen, setIsRequestInputDialogOpen] =
    useState(false);
  const [selectedLetter, setSelectedLetter] = useState<Letter | null>(null);

  const [users, setUsers] = useState<User[]>([]);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [letters, setLetters] = useState<Letter[]>([]);

  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Backend derives user and tenant scope from the HttpOnly session cookie.
  const headerFor = useCallback(
    (_letterId?: string, _orgIdOverride?: string, _projIdOverride?: string) => {
      return {};
    },
    []
  );

  // Normalize backend letter payload to hook shape (ensures .id exists)
  const normalizeLetter = useCallback((l: any) => {
    const id = l?.id ?? (l as any)?._id ?? "";

    const statusRaw =
      l?.statusStartDate ??
      l?.status_start_date ??
      l?.status_startDate ??
      l?.statusstartdate ??
      l?.updatedAt ??
      l?.updated_at ??
      l?.createdAt ??
      l?.created_at;

    let statusStartDate: string | undefined;
    if (statusRaw instanceof Date) {
      statusStartDate = statusRaw.toISOString();
    } else if (typeof statusRaw === "string") {
      statusStartDate = statusRaw;
    }

    let pendency =
      typeof l?.pendencyDays === "number"
        ? l.pendencyDays
        : typeof l?.pendency_days === "number"
        ? l.pendency_days
        : undefined;

    if ((pendency === undefined || Number.isNaN(pendency)) && statusStartDate) {
      const parsed = new Date(statusStartDate);
      if (!Number.isNaN(parsed.getTime())) {
        const diffMs = Date.now() - parsed.getTime();
        pendency = Math.max(0, Math.floor(diffMs / (1000 * 60 * 60 * 24)));
      }
    }

    return {
      ...l,
      id: String(id),
      created_by: l?.created_by ?? l?.createdBy ?? l?.created_by_id ?? "",
      assigned_to: l?.assigned_to ?? l?.assignedTo?.id ?? "",
      organization_id: l?.organization_id ?? l?.organizationId ?? "",
      project_id:
        l?.project_id ??
        l?.projectId ??
        (Array.isArray(l?.projects) ? l.projects[0] : undefined),
      statusStartDate,
      status_start_date: statusStartDate,
      pendencyDays: pendency,
      pendency_days: pendency,
    };
  }, []);

  // Fetch initial data
  useEffect(() => {
    const fetchInitialData = async () => {
      try {
        setIsLoading(true);
        const [usersRes, orgsRes, projectsRes] = await Promise.allSettled([
          api.get<User[]>("/users"),
          api.get<any[]>("/organizations"),
          api.get<any[]>("/projects"),
        ]);

        if (usersRes.status === "fulfilled") {
          // Normalize users and filter to those with drafting capability (role-based)
          const rawUsers = (usersRes.value.data as any[]) ?? [];
          // Only include roles that have drafting capability (docs:create).
          // Based on seeded roles, exclude doccontroller (no docs:create).
          const draftingRoles = new Set([
            "superadmin",
            "orgadmin",
            "orguser",
            "projectadmin",
            "projectuser",
            // common aliases seen in seeds
            "projadmin",
            "projuser",
            "contractmgr_org",
            "contractmgr_proj",
            "headcontract",
          ]);
          const filtered = rawUsers.filter((u: any) => {
            const roles: string[] = Array.isArray(u?.roles) ? u.roles : [];
            // If roles missing, include by default to avoid empty list in dev data
            if (roles.length === 0) return true;
            return roles.some((r) => draftingRoles.has(String(r)));
          });
          const normalized = filtered.map((u: any) => ({
            id: u.id ?? u._id ?? String(u._id ?? u.email ?? u.username ?? ""),
            name: u.username ?? u.name ?? u.full_name ?? u.email ?? "User",
            email: u.email ?? "",
            avatar: u.avatar ?? undefined,
            roles: Array.isArray(u?.roles) ? u.roles : [],
            organizationId:
              (typeof u.organization_id === "string"
                ? u.organization_id
                : u.organization_id
                ? String(u.organization_id)
                : undefined) ??
              (typeof u.organizationId === "string"
                ? u.organizationId
                : undefined) ??
              null,
            projects: Array.isArray(u?.projects)
              ? u.projects.map((p: any) => String(p))
              : [],
          }));
          setUsers(normalized);
        } else {
          console.warn("Failed to load users:", usersRes.reason);
          setUsers([]);
        }

        let normalizedOrgs: Organization[] = [];
        if (orgsRes.status === "fulfilled") {
          // Normalize organizations payloads that may arrive as a paginated response
          const raw = orgsRes.value?.data as any;
          const collection = Array.isArray(raw)
            ? raw
            : Array.isArray(raw?.organizations)
            ? raw.organizations
            : [];

          if (!Array.isArray(raw) && !Array.isArray(raw?.organizations)) {
            console.warn(
              "Unexpected organizations payload shape; attempting fallback fetch",
              raw
            );
          }

          normalizedOrgs = collection.map((o: any) => ({
            id: o.id ?? o._id ?? String(o._id ?? ""),
            name: o.name,
            description: o.description,
          }));
        } else {
          console.warn("Failed to load organizations:", orgsRes.reason);
        }

        // Fallback fetch when the primary axios call fails or returns no records.
        if (normalizedOrgs.length === 0 && typeof window !== "undefined") {
          try {
            const resp = await authenticatedFetch(joinApiUrl("/organizations"), {
              headers: { Accept: "application/json" },
            });
            if (resp.ok) {
              const json = await resp.json();
              const fallback = Array.isArray(json)
                ? json
                : Array.isArray(json?.organizations)
                ? json.organizations
                : [];
              normalizedOrgs = fallback.map((o: any) => ({
                id: o.id ?? o._id ?? String(o._id ?? ""),
                name: o.name,
                description: o.description,
              }));
            } else {
              console.warn(
                "Fallback organization fetch failed",
                resp.status,
                await resp.text().catch(() => "")
              );
            }
          } catch (fallbackError) {
            console.warn("Fallback organization fetch threw", fallbackError);
          }
        }

        setOrganizations(normalizedOrgs);

        if (projectsRes.status === "fulfilled") {
          // Normalize projects and map organization_id -> organizationId for filtering
          const pdata = projectsRes.value.data as any[];
          setProjects(
            pdata.map((p: any) => ({
              id: p.id ?? p._id ?? String(p._id ?? ""),
              name: p.name,
              description: p.description,
              organizationId:
                p.organizationId ??
                p.organization_id ??
                p.organization?.id ??
                "",
            }))
          );
        } else {
          console.warn("Failed to load projects:", projectsRes.reason);
          setProjects([]);
        }
      } catch (e: any) {
        setError(e?.response?.data?.detail || "Failed to load initial data");
      } finally {
        setIsLoading(false);
      }
    };

    fetchInitialData();
  }, []);

  // Fetch letters when tab changes
  useEffect(() => {
    fetchLetters();
  }, [activeTab]);

  const fetchLetters = useCallback(async () => {
    try {
      setIsLoading(true);
      setError(null);
      const params: any = {};
      if (activeTab !== "All") params.tab = activeTab;

      const { data } = await api.get<Letter[]>("/letters", { params });
      const normalized = (Array.isArray(data) ? data : []).map((l: any) =>
        normalizeLetter(l)
      );
      setLetters(normalized as any);
    } catch (e: any) {
      setError(e?.response?.data?.detail || "Failed to load letters");
    } finally {
      setIsLoading(false);
    }
  }, [activeTab]);

  const handleLetterInitiation = useCallback(
    async (payload: CreateLetterInput): Promise<Letter> => {
      try {
        setIsLoading(true);
        setError(null);
        const { data } = await api.post<Letter>(
          "/letters",
          payload,
          headerFor(undefined, payload.organization_id, payload.project_id)
        );

        const created = normalizeLetter(data as any);
        setLetters((prev) => [created as any, ...prev]);
        setIsInitiateDialogOpen(false);

        return created as any;
      } catch (e: any) {
        setError(e?.response?.data?.detail || "Failed to create letter");
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    []
  );

  const handleLetterUpdate = useCallback(
    async (id: string, patch: Partial<Letter>): Promise<Letter> => {
      try {
        setIsLoading(true);
        setError(null);
        const { data } = await api.put<Letter>(
          `/letters/${id}`,
          patch,
          headerFor(id)
        );

        const updated = normalizeLetter(data as any);
        setLetters((prev) =>
          prev.map((letter) => (letter.id === id ? (updated as any) : letter))
        );

        if (selectedLetter?.id === id) {
          setSelectedLetter(updated as any);
        }

        return updated as any;
      } catch (e: any) {
        setError(e?.response?.data?.detail || "Failed to update letter");
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    [selectedLetter]
  );

  const handleInputRequest = useCallback(
    async (
      letterId: string,
      payload: {
        requested_from: string;
        details: string;
        due_date?: string;
        key_points?: string;
        reference_letter_id?: string;
      }
    ) => {
      try {
        setIsLoading(true);
        setError(null);
        const { data } = await api.post(
          `/input-requests/letter/${letterId}`,
          payload,
          headerFor(letterId)
        );

        setIsRequestInputDialogOpen(false);
        return data;
      } catch (e: any) {
        setError(e?.response?.data?.detail || "Failed to create input request");
        throw e;
      } finally {
        setIsLoading(false);
      }
    },
    []
  );

  // Letter workflow actions
  const submitForReview = useCallback(
    async (id: string) => {
      await api.post(`/letters/${id}/submit`, {}, headerFor(id));
      await fetchLetters();
    },
    [fetchLetters]
  );

  const approveLetter = useCallback(
    async (id: string) => {
      await api.post(`/letters/${id}/approve`, {}, headerFor(id));
      await fetchLetters();
    },
    [fetchLetters]
  );

  const completeLetter = useCallback(
    async (id: string) => {
      await api.post(`/letters/${id}/complete`, {}, headerFor(id));
      await fetchLetters();
    },
    [fetchLetters]
  );

  const addComment = useCallback(
    async (id: string, comment: string) => {
      await api.post(`/letters/${id}/comment`, { comment }, headerFor(id));
      await fetchLetters();
    },
    [fetchLetters]
  );

  const reassign = useCallback(
    async (id: string, userId: string) => {
      await api.post(`/letters/${id}/assign/${userId}`, {}, headerFor(id));
      await fetchLetters();
    },
    [fetchLetters]
  );

  // Input request actions
  const listInputRequests = useCallback(
    async (letterId: string) => {
      const { data } = await api.get(
        `/input-requests/letter/${letterId}`,
        headerFor(letterId)
      );
      return data;
    },
    [headerFor]
  );

  const respondToInputRequest = useCallback(
    async (requestId: string, message: string) => {
      const { data } = await api.post(`/input-requests/${requestId}/respond`, {
        message,
      });
      return data;
    },
    []
  );

  const closeInputRequest = useCallback(async (requestId: string) => {
    const { data } = await api.post(`/input-requests/${requestId}/close`);
    return data;
  }, []);

  // Utility functions
  const formatDate = useCallback((dateString: string) => {
    return new Date(dateString).toLocaleDateString();
  }, []);

  const getFilteredLetters = useCallback(() => {
    return letters;
  }, [letters]);

  return {
    // State
    activeTab,
    setActiveTab,
    isInitiateDialogOpen,
    setIsInitiateDialogOpen,
    isRequestInputDialogOpen,
    setIsRequestInputDialogOpen,
    selectedLetter,
    setSelectedLetter,

    // Data
    users,
    organizations,
    projects,
    letters,
    isLoading,
    error,

    // Actions
    handleLetterInitiation,
    handleLetterUpdate,
    handleInputRequest,
    submitForReview,
    approveLetter,
    completeLetter,
    addComment,
    reassign,

    // Input requests
    listInputRequests,
    respondToInputRequest,
    closeInputRequest,

    // Utilities
    formatDate,
    getFilteredLetters,
    fetchLetters,
  };
};

import React, { useEffect, useCallback, useRef, useState } from "react";

// Simple debounce implementation
const debounce = <T extends (...args: any[]) => any>(
  func: T,
  delay: number
): ((...args: Parameters<T>) => void) => {
  let timeoutId: NodeJS.Timeout;
  return (...args: Parameters<T>) => {
    clearTimeout(timeoutId);
    timeoutId = setTimeout(() => func(...args), delay);
  };
};

// Performance monitoring hook
export const usePerformanceMonitor = () => {
  const [metrics, setMetrics] = useState({
    renderTime: 0,
    memoryUsage: 0,
    componentCount: 0,
  });

  const startTime = useRef<number>(0);

  useEffect(() => {
    startTime.current = performance.now();

    return () => {
      const endTime = performance.now();
      const renderTime = endTime - startTime.current;

      setMetrics((prev) => ({
        ...prev,
        renderTime,
        memoryUsage: (performance as any).memory?.usedJSHeapSize || 0,
      }));
    };
  }, []);

  return metrics;
};

// Debounced callback hook
export const useDebouncedCallback = <T extends (...args: any[]) => any>(
  callback: T,
  delay: number = 300
): T => {
  const debouncedCallback = useCallback(debounce(callback, delay), [
    callback,
    delay,
  ]);

  return debouncedCallback as T;
};

// Throttled callback hook
export const useThrottledCallback = <T extends (...args: any[]) => any>(
  callback: T,
  delay: number = 100
): T => {
  const lastRun = useRef<number>(0);

  const throttledCallback = useCallback(
    (...args: any[]) => {
      const now = Date.now();
      if (now - lastRun.current >= delay) {
        lastRun.current = now;
        return callback(...args);
      }
    },
    [callback, delay]
  );

  return throttledCallback as T;
};

// Intersection Observer hook for lazy loading
export const useIntersectionObserver = (
  options: IntersectionObserverInit = {}
) => {
  const [isIntersecting, setIsIntersecting] = useState(false);
  const [hasIntersected, setHasIntersected] = useState(false);
  const elementRef = useRef<HTMLElement | null>(null);

  useEffect(() => {
    const element = elementRef.current;
    if (!element) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        setIsIntersecting(entry.isIntersecting);
        if (entry.isIntersecting && !hasIntersected) {
          setHasIntersected(true);
        }
      },
      {
        threshold: 0.1,
        rootMargin: "50px",
        ...options,
      }
    );

    observer.observe(element);

    return () => {
      observer.unobserve(element);
    };
  }, [hasIntersected, options]);

  return { elementRef, isIntersecting, hasIntersected };
};

// Image lazy loading hook
export const useLazyImage = (src: string, placeholder?: string) => {
  const [imageSrc, setImageSrc] = useState(placeholder || "");
  const [isLoaded, setIsLoaded] = useState(false);
  const [isError, setIsError] = useState(false);
  const { elementRef, hasIntersected } = useIntersectionObserver();

  useEffect(() => {
    if (!hasIntersected) return;

    const img = new Image();
    img.onload = () => {
      setImageSrc(src);
      setIsLoaded(true);
    };
    img.onerror = () => {
      setIsError(true);
    };
    img.src = src;
  }, [src, hasIntersected]);

  return { elementRef, imageSrc, isLoaded, isError };
};

// Component lazy loading hook
export const useLazyComponent = <T extends React.ComponentType<any>>(
  importFunc: () => Promise<{ default: T }>
) => {
  const [Component, setComponent] = useState<T | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  const loadComponent = useCallback(async () => {
    if (Component || isLoading) return;

    setIsLoading(true);
    setError(null);

    try {
      const module = await importFunc();
      setComponent(() => module.default);
    } catch (err) {
      setError(err as Error);
    } finally {
      setIsLoading(false);
    }
  }, [Component, isLoading, importFunc]);

  return { Component, isLoading, error, loadComponent };
};

// Memory usage monitoring hook
export const useMemoryMonitor = () => {
  const [memoryInfo, setMemoryInfo] = useState({
    usedJSHeapSize: 0,
    totalJSHeapSize: 0,
    jsHeapSizeLimit: 0,
  });

  useEffect(() => {
    const updateMemoryInfo = () => {
      if ((performance as any).memory) {
        setMemoryInfo({
          usedJSHeapSize: (performance as any).memory.usedJSHeapSize,
          totalJSHeapSize: (performance as any).memory.totalJSHeapSize,
          jsHeapSizeLimit: (performance as any).memory.jsHeapSizeLimit,
        });
      }
    };

    updateMemoryInfo();
    const interval = setInterval(updateMemoryInfo, 5000); // Update every 5 seconds

    return () => clearInterval(interval);
  }, []);

  return memoryInfo;
};

// Bundle size analyzer (development only)
export const useBundleAnalyzer = () => {
  const [bundleInfo, setBundleInfo] = useState({
    chunks: [] as string[],
    totalSize: 0,
  });

  useEffect(() => {
    if (process.env.NODE_ENV === "development") {
      // Analyze loaded chunks
      const scripts = Array.from(document.querySelectorAll("script[src]"));
      const chunks = scripts
        .map((script) => (script as HTMLScriptElement).src)
        .filter((src) => src.includes("chunk") || src.includes("vendor"));

      setBundleInfo({
        chunks,
        totalSize: chunks.length,
      });
    }
  }, []);

  return bundleInfo;
};

// Performance optimization utilities
export const performanceUtils = {
  // Measure component render time
  measureRender: (componentName: string, renderFn: () => void) => {
    const start = performance.now();
    renderFn();
    const end = performance.now();
    console.log(`${componentName} render time: ${end - start}ms`);
  },

  // Preload critical resources
  preloadResource: (href: string, as: string = "script") => {
    const link = document.createElement("link");
    link.rel = "preload";
    link.href = href;
    link.as = as;
    document.head.appendChild(link);
  },

  // Prefetch next page resources
  prefetchResource: (href: string) => {
    const link = document.createElement("link");
    link.rel = "prefetch";
    link.href = href;
    document.head.appendChild(link);
  },

  // Check if user prefers reduced motion
  prefersReducedMotion: () => {
    return window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  },

  // Get connection information
  getConnectionInfo: () => {
    const connection = (navigator as any).connection;
    if (!connection) return null;

    return {
      effectiveType: connection.effectiveType,
      downlink: connection.downlink,
      rtt: connection.rtt,
      saveData: connection.saveData,
    };
  },

  // Optimize images based on connection
  getOptimalImageSize: (baseSize: number) => {
    const connection = performanceUtils.getConnectionInfo();
    if (!connection) return baseSize;

    if (connection.saveData || connection.effectiveType === "slow-2g") {
      return Math.floor(baseSize * 0.5);
    }
    if (connection.effectiveType === "2g") {
      return Math.floor(baseSize * 0.7);
    }
    if (connection.effectiveType === "3g") {
      return Math.floor(baseSize * 0.85);
    }
    return baseSize;
  },
};

// React.memo with custom comparison
export const createMemoComponent = <P extends object>(
  Component: React.ComponentType<P>,
  propsAreEqual?: (prevProps: P, nextProps: P) => boolean
) => {
  return React.memo(Component, propsAreEqual);
};

// HOC for performance monitoring
export const withPerformanceMonitoring = <P extends object>(
  WrappedComponent: React.ComponentType<P>,
  componentName: string
) => {
  return React.memo((props: P) => {
    const metrics = usePerformanceMonitor();

    useEffect(() => {
      if (process.env.NODE_ENV === "development") {
        console.log(`${componentName} performance:`, metrics);
      }
    }, [metrics]);

    return React.createElement(WrappedComponent, props);
  });
};

export default {
  usePerformanceMonitor,
  useDebouncedCallback,
  useThrottledCallback,
  useIntersectionObserver,
  useLazyImage,
  useLazyComponent,
  useMemoryMonitor,
  useBundleAnalyzer,
  performanceUtils,
  createMemoComponent,
  withPerformanceMonitoring,
};

import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { Link } from "react-router-dom";
import {
  createContractUploadSession,
  downloadContractDocument,
  uploadContractsMultipart,
  uploadContractInChunks,
  getContractStatus,
  UploadResult,
  StatusResponse,
} from "@/services/contracts-api";
import { extractErrorMessage } from "@/lib/error-logger";
import { api } from "@/services/api";
import PageHeader from "@/components/ui/PageHeader";
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
  CardFooter,
} from "@/components/ui/card";
import Badge from "@/components/ui/badge";
import {
  UploadCloud,
  Loader2,
  FileText,
  Building2,
  FolderOpen,
  X,
  CheckCircle,
  AlertCircle,
  Clock,
  Download,
  RotateCcw,
  Upload as UploadIcon,
} from "lucide-react";

type UploadProgress = {
  file: File;
  mode: "multipart" | "chunked";
  progress: number; // 0-100
  upload_id?: string;
  document_id?: string;
  status?: "queued" | "processing" | "completed" | "failed" | "unknown";
  categories?: string[] | null;
  error?: string | null;
  processing_stage?: string | null;
  stage_label?: string | null;
};

type Organization = { id: string; name: string; shortName?: string | null };
type Project = { _id: string; name: string; organization_id: string };

type PrevUpload = {
  document_id: string;
  upload_id?: string | null;
  filename: string;
  status?: string;
  categories?: string[] | null;
  createdAt?: string | null;
  size?: number | null;
};

const bytesToHuman = (n: number) => {
  if (n < 1024) return `${n} B`;
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`;
  if (n < 1024 * 1024 * 1024) return `${(n / (1024 * 1024)).toFixed(1)} MB`;
  return `${(n / (1024 * 1024 * 1024)).toFixed(1)} GB`;
};

const statusVariant = (
  s?: UploadProgress["status"]
): "primary" | "success" | "danger" | "neutral" => {
  if (s === "completed") return "success";
  if (s === "failed") return "danger";
  if (s === "processing" || s === "queued") return "primary";
  return "neutral";
};

const getStatusIcon = (status?: UploadProgress["status"]) => {
  switch (status) {
    case "completed":
      return <CheckCircle className="h-4 w-4" />;
    case "failed":
      return <AlertCircle className="h-4 w-4" />;
    case "processing":
    case "queued":
      return <Clock className="h-4 w-4" />;
    default:
      return <FileText className="h-4 w-4" />;
  }
};

const ContractsUploadPage: React.FC = () => {
  // Organization/Project name fetching
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [orgLoading, setOrgLoading] = useState<boolean>(false);
  const [projLoading, setProjLoading] = useState<boolean>(false);

  const [orgId, setOrgId] = useState<string>(
    () => window.localStorage.getItem("org_id") || ""
  );
const [projId, setProjId] = useState<string>(
  () => window.localStorage.getItem("proj_id") || ""
);

  const parseOrganizationsResponse = useCallback((payload: any): Organization[] => {
    const collection = Array.isArray(payload)
      ? payload
      : Array.isArray(payload?.organizations)
      ? payload.organizations
      : [];

    return collection
      .map((org: any) => {
        const id =
          org?.id ??
          org?._id ??
          (typeof org?._id !== "undefined" ? String(org._id) : "");
        const name = org?.name ?? org?.title ?? "";
        if (!id || !name) {
          return null;
        }
        return {
          id: String(id),
          name: String(name),
          shortName: org?.shortName ?? org?.short_name ?? null,
        } as Organization;
      })
      .filter(Boolean) as Organization[];
  }, []);

  // Files and uploads
  const [files, setFiles] = useState<File[]>([]);
  const [uploads, setUploads] = useState<UploadProgress[]>([]);
  const [prevUploads, setPrevUploads] = useState<PrevUpload[]>([]);
  const [prevLoading, setPrevLoading] = useState<boolean>(false);
  const [hasMore, setHasMore] = useState<boolean>(false);
  const PAGE_SIZE = 50;
  const pollTimers = useRef<Record<string, any>>({});
  const uploadAbortRef = useRef<AbortController | null>(null);
  const [uploadingBatch, setUploadingBatch] = useState(false);

  // Drag & Drop
  const [dragging, setDragging] = useState(false);
  const dropRef = useRef<HTMLDivElement | null>(null);

  // Fetch organizations on mount
  useEffect(() => {
    const fetchOrgs = async () => {
      setOrgLoading(true);
      try {
        const { data } = await api.get("/organizations", {
          params: { limit: 50 },
        });
        const list = parseOrganizationsResponse(data);
        setOrganizations(list);
      } catch (e) {
        console.error("Failed to fetch organizations", e);
        setOrganizations([]);
      } finally {
        setOrgLoading(false);
      }
    };
    fetchOrgs();
  }, [parseOrganizationsResponse]);

  // Fetch projects when orgId changes
  useEffect(() => {
    const fetchProjects = async () => {
      if (!orgId) {
        setProjects([]);
        return;
      }
      setProjLoading(true);
      try {
        const { data } = await api.get("/projects", {
          params: { organization_id: orgId },
        });
        const list: Project[] = (data || []).map((p: any) => ({
          _id: p._id ?? p.id ?? "",
          name: p.name ?? "",
          organization_id: p.organization_id ?? "",
        }));
        setProjects(list);
      } catch (e) {
        console.error("Failed to fetch projects", e);
      } finally {
        setProjLoading(false);
      }
    };
    fetchProjects();
  }, [orgId]);

  // Persist selections
  useEffect(() => {
    if (orgId) window.localStorage.setItem("org_id", orgId);
    if (projId) window.localStorage.setItem("proj_id", projId);
  }, [orgId, projId]);

  // Load previously uploaded contracts for selected org/project
  const refreshPrevUploads = useCallback(
    async (append: boolean = false) => {
      if (!orgId) {
        setPrevUploads([]);
        setHasMore(false);
        return;
      }
      setPrevLoading(true);
      try {
        const skip = append ? prevUploads.length : 0;
        const { data } = await api.get("/contracts/list", {
          params: {
            organization_id: orgId,
            project_id: projId || undefined,
            limit: PAGE_SIZE,
            skip,
          },
        });
        const uploads: PrevUpload[] = (data?.uploads || []).map((r: any) => ({
          document_id: String(r.document_id ?? ""),
          upload_id: r.upload_id ?? null,
          filename: r.filename ?? "file",
          status: r.status ?? "unknown",
          categories: r.categories ?? null,
          createdAt: r.createdAt ?? null,
          size: r.size ?? null,
        }));
        setHasMore(uploads.length === PAGE_SIZE);
        setPrevUploads((prev) => (append ? [...prev, ...uploads] : uploads));
      } catch (e) {
        console.error("Failed to load previous uploads", e);
        if (!append) setPrevUploads([]);
        setHasMore(false);
      } finally {
        setPrevLoading(false);
      }
    },
    [orgId, projId, prevUploads.length]
  );

  // Initial and org/project change refresh
  useEffect(() => {
    refreshPrevUploads();
  }, [refreshPrevUploads]);

  const onSelectFiles = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const list = e.target.files ? Array.from(e.target.files) : [];
      if (list.length === 0) return;
      setFiles((prev) => {
        const key = (f: File) =>
          `${f.name}__${f.size}__${(f as any).lastModified ?? ""}`;
        const existing = new Set(prev.map(key));
        const merged: File[] = [...prev];
        for (const f of list) {
          const k = key(f);
          if (!existing.has(k)) {
            merged.push(f);
            existing.add(k);
          }
        }
        // Allow re-selecting the same files by clearing the input's value.
        if (e.target) (e.target as HTMLInputElement).value = "";
        return merged;
      });
    },
    []
  );

  const removeFile = useCallback((idx: number) => {
    setFiles((prev) => prev.filter((_, i) => i !== idx));
  }, []);

  const clearFiles = useCallback(() => {
    setFiles([]);
  }, []);

  const canUpload = useMemo(
    () => orgId && projId && files.length > 0,
    [orgId, projId, files.length]
  );

  const stopPolling = useCallback((uploadId: string) => {
    const timers = pollTimers.current;
    if (timers[uploadId]) {
      clearInterval(timers[uploadId]);
      delete timers[uploadId];
    }
  }, []);

  const pollStatus = useCallback(
    (uploadId: string) => {
      stopPolling(uploadId);
      const startedAt = Date.now();
      const timer = setInterval(async () => {
        try {
          const st: StatusResponse = await getContractStatus(uploadId);
          setUploads((prev) =>
            prev.map((u) =>
              u.upload_id === uploadId
                ? {
                    ...u,
                    document_id: st.document_id || u.document_id,
                    status: st.status,
                    progress:
                      typeof st.progress === "number"
                        ? st.progress
                        : st.status === "completed"
                        ? 100
                        : u.progress,
                    categories: st.categories || null,
                    error: st.error || null,
                    processing_stage: st.processing_stage || null,
                    stage_label: st.stage_label || null,
                  }
                : u
            )
          );
          if (st.status === "completed" || st.status === "failed") {
            stopPolling(uploadId);
            // Refresh the "Previously Uploaded" list when an upload completes
            if (st.status === "completed") {
              refreshPrevUploads();
            }
          }
          if (Date.now() - startedAt > 10 * 60 * 1000) {
            stopPolling(uploadId);
            setUploads((prev) =>
              prev.map((u) =>
                u.upload_id === uploadId
                  ? {
                      ...u,
                      status: u.status === "completed" ? "completed" : "failed",
                      error: u.status === "completed" ? u.error || null : "Upload processing timed out. Refresh the page to verify final status.",
                    }
                  : u
              )
            );
          }
        } catch {
          if (Date.now() - startedAt > 10 * 60 * 1000) {
            stopPolling(uploadId);
          }
        }
      }, 1500);
      pollTimers.current[uploadId] = timer;
    },
    [stopPolling, refreshPrevUploads]
  );

  useEffect(() => {
    return () => {
      uploadAbortRef.current?.abort();
      Object.keys(pollTimers.current).forEach((uploadId) => stopPolling(uploadId));
    };
  }, [stopPolling]);

  // When all uploads in the current batch finish (completed or failed),
  // refresh the Previously Uploaded list so the new files appear after page reloads too.
  useEffect(() => {
    if (uploads.length === 0) return;
    const allDone = uploads.every(
      (u) => u.status === "completed" || u.status === "failed"
    );
    if (allDone) {
      refreshPrevUploads();
    }
  }, [uploads, refreshPrevUploads]);

  // Generic download helper
  const downloadBy = useCallback(
    async (params: { document_id?: string; filename?: string }) => {
      try {
        if (!params.document_id) {
          window.alert("File is not ready to download yet.");
          return;
        }
        const fname = params.filename || "contract";
        const blob = await downloadContractDocument(params.document_id);
        const url = window.URL.createObjectURL(blob);
        const link = document.createElement("a");
        link.href = url;
        link.download = fname;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        window.URL.revokeObjectURL(url);
      } catch (e) {
        console.error("Download failed", e);
        window.alert(extractErrorMessage(e, "Failed to download file."));
      }
    },
    []
  );

  // Download a just-uploaded item (progress list)
  const handleDownloadUpload = useCallback(
    (u: UploadProgress) => {
      const filename = (u.file && u.file.name) || "contract.pdf";
      return downloadBy({ document_id: u.document_id, filename });
    },
    [downloadBy]
  );

  // Download an existing (previously uploaded) item
  const handleDownloadExisting = useCallback(
    (pu: PrevUpload) => {
      const filename = pu.filename || "contract.pdf";
      return downloadBy({ document_id: pu.document_id, filename });
    },
    [downloadBy]
  );

  // Drag & Drop handlers
  const onDragOver = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      if (!dragging) setDragging(true);
    },
    [dragging]
  );

  const onDragLeave = useCallback(
    (e: React.DragEvent<HTMLDivElement>) => {
      e.preventDefault();
      e.stopPropagation();
      if (dragging) setDragging(false);
    },
    [dragging]
  );

  const onDrop = useCallback((e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    e.stopPropagation();
    setDragging(false);
    const dt = e.dataTransfer;
    if (dt && dt.files && dt.files.length > 0) {
      const newFiles = Array.from(dt.files);
      setFiles((prev) => {
        const key = (f: File) =>
          `${f.name}__${f.size}__${(f as any).lastModified ?? ""}`;
        const existing = new Set(prev.map(key));
        const merged = [...prev];
        for (const file of newFiles) {
          const fileKey = key(file);
          if (!existing.has(fileKey)) {
            existing.add(fileKey);
            merged.push(file);
          }
        }
        return merged;
      });
      dt.clearData();
    }
  }, []);

  const uploadFile = useCallback(
    async (f: File, controller: AbortController) => {
      const CHUNK_THRESHOLD = 5 * 1024 * 1024;
      const isChunked = f.size > CHUNK_THRESHOLD;

      try {
        const session = await createContractUploadSession(
          {
            filename: f.name,
            organization_id: orgId,
            project_id: projId,
          },
          controller.signal
        );
        setUploads((prev) =>
          prev.map((u) =>
            u.file === f
              ? {
                  ...u,
                  upload_id: session.upload_id,
                  error: null,
                }
              : u
          )
        );

        if (!isChunked) {
          const resp = await uploadContractsMultipart(
            [f],
            orgId,
            projId || undefined,
            undefined,
            [session.upload_id],
            controller.signal
          );
          const result: UploadResult | undefined = resp.results?.[0];
          if (!result) {
            throw new Error("Upload did not return a result.");
          }
          setUploads((prev) =>
            prev.map((u) =>
              u.file === f
                ? {
                    ...u,
                    progress: 100,
                    upload_id: result.upload_id,
                    document_id: result.document_id,
                    status: "queued",
                    error: null,
                  }
                : u
            )
          );
          pollStatus(result.upload_id);
          return;
        }

        const result = await uploadContractInChunks(
          f,
          orgId,
          projId || undefined,
          {
            chunkSize: session.max_chunk_size_bytes,
            uploadId: session.upload_id,
            signal: controller.signal,
            onProgress: (p) => {
              setUploads((prev) =>
                prev.map((u) => (u.file === f ? { ...u, progress: p } : u))
              );
            },
          }
        );
        setUploads((prev) =>
          prev.map((u) =>
            u.file === f
              ? {
                  ...u,
                  progress: 100,
                  upload_id: result.upload_id,
                  document_id: result.document_id || undefined,
                  status: "queued",
                  error: null,
                }
              : u
          )
        );
        if (result.upload_id) {
          pollStatus(result.upload_id);
        }
      } catch (e: any) {
        const isCanceled =
          e?.name === "CanceledError" ||
          e?.code === "ERR_CANCELED" ||
          e?.message === "Upload canceled";
        const message = isCanceled
          ? "Upload canceled by user."
          : extractErrorMessage(e, "Upload failed.");
        setUploads((prev) =>
          prev.map((u) =>
            u.file === f ? { ...u, status: "failed", error: message } : u
          )
        );
      }
    },
    [orgId, projId, pollStatus]
  );

  const handleUpload = useCallback(async () => {
    if (!orgId) {
      window.alert("Please select an organization.");
      return;
    }
    if (!projId) {
      window.alert("Please select a project.");
      return;
    }
    if (files.length === 0) {
      window.alert("Select one or more files.");
      return;
    }

    const controller = new AbortController();
    uploadAbortRef.current = controller;
    setUploadingBatch(true);
    const CHUNK_THRESHOLD = 5 * 1024 * 1024;

    const smallFiles = files.filter((f) => f.size <= CHUNK_THRESHOLD);
    const largeFiles = files.filter((f) => f.size > CHUNK_THRESHOLD);

    setUploads([
      ...smallFiles.map<UploadProgress>((f) => ({
        file: f,
        mode: "multipart",
        progress: 0,
      })),
      ...largeFiles.map<UploadProgress>((f) => ({
        file: f,
        mode: "chunked",
        progress: 0,
      })),
    ]);

    try {
      for (const f of smallFiles) {
        if (controller.signal.aborted) break;
        await uploadFile(f, controller);
      }
      for (const f of largeFiles) {
        if (controller.signal.aborted) break;
        await uploadFile(f, controller);
      }
    } finally {
      if (uploadAbortRef.current === controller) {
        uploadAbortRef.current = null;
      }
      setUploadingBatch(false);
    }
  }, [files, orgId, projId, uploadFile]);

  const handleCancelUploads = useCallback(() => {
    uploadAbortRef.current?.abort();
    setUploadingBatch(false);
    setUploads((prev) =>
      prev.map((upload) =>
        upload.status === "completed" || upload.status === "failed"
          ? upload
          : { ...upload, status: "failed", error: upload.error || "Upload canceled by user." }
      )
    );
  }, []);

  const retryUpload = useCallback(
    async (upload: UploadProgress) => {
      if (!orgId || !projId || uploadingBatch) {
        return;
      }
      if (upload.upload_id) {
        stopPolling(upload.upload_id);
      }
      const controller = new AbortController();
      uploadAbortRef.current = controller;
      setUploadingBatch(true);
      setUploads((prev) =>
        prev.map((item) =>
          item.file === upload.file
            ? {
                ...item,
                progress: 0,
                upload_id: undefined,
                document_id: undefined,
                status: undefined,
                categories: null,
                error: null,
              }
            : item
        )
      );
      try {
        await uploadFile(upload.file, controller);
      } finally {
        if (uploadAbortRef.current === controller) {
          uploadAbortRef.current = null;
        }
        setUploadingBatch(false);
      }
    },
    [orgId, projId, stopPolling, uploadFile, uploadingBatch]
  );

  return (
    <div className="max-w-7xl mx-auto p-6 space-y-6">
      <PageHeader
        icon={<UploadCloud className="h-6 w-6" />}
        title="Upload Contracts"
        description="Upload and organize contract documents by organization and project"
      />

      {/* Organization & Project Selection */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Building2 className="h-5 w-5" />
            Contract Details
          </CardTitle>
          <CardDescription>
            Please fill in the contract information and select the associated
            organization and project
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">
                Organization *
              </label>
              <select
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                value={orgId}
                onChange={(e) => {
                  setOrgId(e.target.value);
                  setProjId("");
                }}
                disabled={orgLoading}
              >
                <option value="">Select organization</option>
                {organizations.map((o) => (
                  <option key={o.id} value={o.id}>
                    {o.name}
                  </option>
                ))}
              </select>
              {orgLoading && (
                <p className="text-xs text-gray-500 flex items-center gap-1">
                  <Loader2 className="h-3 w-3 animate-spin" />
                  Loading organizations...
                </p>
              )}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium text-gray-700">
                Project *
              </label>
              <select
                className="w-full px-3 py-2 border border-gray-300 rounded-md shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 disabled:bg-gray-50 disabled:text-gray-500"
                value={projId}
                onChange={(e) => setProjId(e.target.value)}
                disabled={!orgId || projLoading}
              >
                <option value="">
                  {!orgId
                    ? "Please select an organization first"
                    : "Select project"}
                </option>
                {projects.map((p) => (
                  <option key={p._id} value={p._id}>
                    {p.name}
                  </option>
                ))}
              </select>
              {projLoading && (
                <p className="text-xs text-gray-500 flex items-center gap-1">
                  <Loader2 className="h-3 w-3 animate-spin" />
                  Loading projects...
                </p>
              )}
            </div>
          </div>
        </CardContent>
        <CardFooter>
          <button
            onClick={() => refreshPrevUploads(true)}
            disabled={prevLoading || !hasMore}
            className={`px-4 py-2 rounded-md text-sm font-medium ${
              prevLoading || !hasMore
                ? "bg-gray-200 text-gray-500 cursor-not-allowed"
                : "bg-white border border-gray-300 text-gray-800 hover:bg-gray-50"
            }`}
            title={hasMore ? "Load more uploads" : "No more items"}
          >
            {prevLoading
              ? "Loading..."
              : hasMore
              ? "Load more"
              : "No more items"}
          </button>
        </CardFooter>
      </Card>

      {/* File Upload Area */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FolderOpen className="h-5 w-5" />
            Contract Files *
          </CardTitle>
          <CardDescription>
            Supported formats: PDF and DOCX. Server-side validation enforces the
            upload limits and file security checks.
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div
            ref={dropRef}
            onDragOver={onDragOver}
            onDragLeave={onDragLeave}
            onDrop={onDrop}
            className={`
              relative border-2 border-dashed rounded-lg p-8 text-center transition-colors
              ${
                dragging
                  ? "border-blue-500 bg-blue-50"
                  : "border-gray-300 hover:border-gray-400"
              }
            `}
          >
            <input
              type="file"
              multiple
              accept=".pdf,.docx"
              onChange={onSelectFiles}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
            <div className="space-y-4">
              <div className="mx-auto w-12 h-12 bg-gray-100 rounded-full flex items-center justify-center">
                <UploadCloud className="h-6 w-6 text-gray-600" />
              </div>
              <div>
                <p className="text-lg font-medium text-gray-900">
                  {dragging
                    ? "Drop files here"
                    : "Choose files or drag and drop"}
                </p>
                <p className="text-sm text-gray-500 mt-1">
                  PDF and DOCX only. Large files upload in secure chunks.
                </p>
              </div>
            </div>
          </div>

          {/* Selected Files List */}
          {files.length > 0 && (
            <div className="mt-6 space-y-3">
              <div className="flex items-center justify-between">
                <h4 className="text-sm font-medium text-gray-900">
                  Selected Files ({files.length})
                </h4>
                <button
                  onClick={clearFiles}
                  className="text-sm text-red-600 hover:text-red-700"
                >
                  Clear all
                </button>
              </div>
              <div className="space-y-2">
                {files.map((file, idx) => (
                  <div
                    key={`${file.name}-${idx}`}
                    className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                  >
                    <div className="flex items-center gap-3">
                      <FileText className="h-5 w-5 text-gray-400" />
                      <div>
                        <p className="text-sm font-medium text-gray-900">
                          {file.name}
                        </p>
                        <p className="text-xs text-gray-500">
                          {bytesToHuman(file.size)}
                        </p>
                      </div>
                    </div>
                    <button
                      onClick={() => removeFile(idx)}
                      className="p-1 text-gray-400 hover:text-red-500 transition-colors"
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </CardContent>
        <CardFooter className="flex gap-3">
          <button
            onClick={handleUpload}
            disabled={!canUpload || uploadingBatch}
            className={`
              flex-1 flex items-center justify-center gap-2 px-4 py-2 rounded-md font-medium transition-colors
              ${
                canUpload && !uploadingBatch
                  ? "bg-blue-600 hover:bg-blue-700 text-white"
                  : "bg-gray-300 text-gray-500 cursor-not-allowed"
              }
            `}
          >
            {uploadingBatch ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <UploadIcon className="h-4 w-4" />
            )}
            {uploadingBatch ? "Uploading..." : `Upload Contract${files.length > 1 ? "s" : ""}`}
          </button>
          {uploadingBatch && (
            <button
              onClick={handleCancelUploads}
              className="px-4 py-2 rounded-md font-medium border border-gray-300 text-gray-700 hover:bg-gray-50"
            >
              Cancel Uploads
            </button>
          )}
        </CardFooter>
      </Card>

      {/* Previously Uploaded */}
      <Card>
        <CardHeader>
          <div className="flex items-center justify-between w-full">
            <div>
              <CardTitle>Previously Uploaded</CardTitle>
              <CardDescription>
                Recent uploads for the selected organization and project
              </CardDescription>
            </div>
            <div className="ml-auto">
              <Link
                to="/contracts/search"
                className="inline-flex items-center px-3 py-2 text-sm font-medium rounded-md bg-blue-600 text-white hover:bg-blue-700 border border-blue-600 transition-colors"
                title="Go to Search Clauses"
              >
                Search Clauses
              </Link>
            </div>
          </div>
        </CardHeader>
        <CardContent>
          {prevLoading ? (
            <p className="text-sm text-gray-500 flex items-center gap-1">
              <Loader2 className="h-4 w-4 animate-spin" /> Loading...
            </p>
          ) : prevUploads.length === 0 ? (
            <p className="text-sm text-gray-500">No previous uploads found.</p>
          ) : (
            <ul className="divide-y divide-gray-200">
              {prevUploads.map((pu, idx) => (
                <li
                  key={(pu.document_id || pu.upload_id || "") + String(idx)}
                  className="py-3 flex items-center justify-between gap-4"
                >
                  <div className="flex items-center gap-3 min-w-0">
                    <FileText className="h-5 w-5 text-gray-400" />
                    <div className="min-w-0">
                      <div className="text-sm font-medium text-gray-900 truncate">
                        {pu.filename}
                      </div>
                      <div className="text-xs text-gray-500">
                        {pu.size ? `${bytesToHuman(pu.size)} • ` : ""}
                        {pu.createdAt
                          ? new Date(pu.createdAt).toLocaleString()
                          : ""}
                      </div>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    <Badge
                      variant={statusVariant(
                        (pu.status as any) || ("unknown" as any)
                      )}
                    >
                      {pu.status || "unknown"}
                    </Badge>
                    <button
                      onClick={() => handleDownloadExisting(pu)}
                      title="Download file"
                      className="p-1 rounded border border-blue-200 text-blue-600 hover:bg-blue-50"
                    >
                      <Download className="h-4 w-4" />
                    </button>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>

      {/* Upload Progress */}
      {uploads.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Upload Progress</CardTitle>
            <CardDescription>
              Track the progress of your contract uploads
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="space-y-4">
              {uploads.map((upload, idx) => (
                <div key={`${upload.file.name}-${idx}`} className="space-y-2">
                  <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                      {getStatusIcon(upload.status)}
                      <div>
                        <p className="text-sm font-medium text-gray-900">
                          {upload.file.name}
                        </p>
                        <p className="text-xs text-gray-500">
                          {bytesToHuman(upload.file.size)} • {upload.mode}
                        </p>
                        {upload.stage_label && (
                          <p className="text-xs text-blue-600">
                            {upload.stage_label}
                          </p>
                        )}
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                      {upload.status === "failed" && (
                        <button
                          onClick={() => retryUpload(upload)}
                          disabled={uploadingBatch}
                          title="Retry file upload"
                          className={`p-1 rounded border text-sm inline-flex items-center gap-1 ${
                            uploadingBatch
                              ? "border-gray-200 text-gray-400 cursor-not-allowed"
                              : "border-amber-200 text-amber-700 hover:bg-amber-50"
                          }`}
                        >
                          <RotateCcw className="h-4 w-4" />
                        </button>
                      )}
                      {upload.status && (
                        <Badge variant={statusVariant(upload.status)}>
                          {upload.status}
                        </Badge>
                      )}
                      <span className="text-sm text-gray-500">
                        {upload.progress}%
                      </span>
                      <button
                        onClick={() => handleDownloadUpload(upload)}
                        disabled={
                          !(upload.status === "completed" || upload.document_id)
                        }
                        title="Download file"
                        className={`p-1 rounded border text-sm inline-flex items-center gap-1 ${
                          upload.status === "completed" || upload.document_id
                            ? "border-blue-200 text-blue-600 hover:bg-blue-50"
                            : "border-gray-200 text-gray-400 cursor-not-allowed"
                        }`}
                      >
                        <Download className="h-4 w-4" />
                      </button>
                    </div>
                  </div>

                  {/* Progress Bar */}
                  <div className="w-full bg-gray-200 rounded-full h-2">
                    <div
                      className={`h-2 rounded-full transition-all duration-300 ${
                        upload.status === "completed"
                          ? "bg-green-500"
                          : upload.status === "failed"
                          ? "bg-red-500"
                          : "bg-blue-500"
                      }`}
                      style={{ width: `${upload.progress}%` }}
                    />
                  </div>

                  {/* Error Message */}
                  {upload.error && (
                    <p className="text-sm text-red-600 bg-red-50 p-2 rounded">
                      {upload.error}
                    </p>
                  )}

                  {/* Categories */}
                  {upload.categories && upload.categories.length > 0 && (
                    <div className="flex flex-wrap gap-1">
                      {upload.categories.map((cat) => (
                        <Badge key={cat} variant="outline" className="text-xs">
                          {cat}
                        </Badge>
                      ))}
                    </div>
                  )}
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default ContractsUploadPage;

import React, { useState, useEffect } from "react";
import PageHeader from "@/components/ui/PageHeader";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import Badge from "@/components/ui/badge";
import { SkeletonCard } from "@/components/ui/skeleton";
import { getSearchAnalytics } from "@/services/search-api";
import { listDocuments } from "@/services/documents-api";
import { listOrganizations } from "@/services/organizations-api";
import { listProjects } from "@/services/projects-api";
import {
  BarChart3,
  FileText,
  Building2,
  FolderOpen,
  TrendingUp,
  Clock,
  Search,
  Users,
  Activity,
  Calendar,
  Download,
  Eye,
} from "lucide-react";

interface DashboardStats {
  totalDocuments: number;
  totalOrganizations: number;
  totalProjects: number;
  recentUploads: number;
  searchesThisWeek: number;
  popularSearches: Array<{ term: string; count: number }>;
  recentActivity: Array<{
    id: string;
    type: "upload" | "search" | "download" | "view";
    description: string;
    timestamp: string;
    user?: string;
  }>;
  documentsByCategory: Array<{ category: string; count: number }>;
  uploadTrend: Array<{ date: string; count: number }>;
}

const DashboardPage: React.FC = () => {
  const [stats, setStats] = useState<DashboardStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [timeRange, setTimeRange] = useState<"7d" | "30d" | "90d">("30d");

  useEffect(() => {
    loadDashboardData();
  }, [timeRange]);

  const loadDashboardData = async () => {
    setLoading(true);
    setError(null);

    try {
      // Calculate date range
      const endDate = new Date();
      const startDate = new Date();
      const days = timeRange === "7d" ? 7 : timeRange === "30d" ? 30 : 90;
      startDate.setDate(endDate.getDate() - days);

      // Fetch data in parallel
      const [
        documentsResponse,
        organizationsResponse,
        projectsResponse,
        analyticsResponse,
      ] = await Promise.all([
        listDocuments({ limit: 1000 }), // Get all documents for stats
        listOrganizations(),
        listProjects(),
        getSearchAnalytics({
          from: startDate.toISOString().split("T")[0],
          to: endDate.toISOString().split("T")[0],
        }).catch(() => null), // Analytics might not be available
      ]);

      // Process documents data
      const documents = documentsResponse.documents || [];
      const recentUploads = documents.filter((doc) => {
        if (!doc.createdAt) return false;
        const uploadDate = new Date(doc.createdAt);
        return uploadDate >= startDate;
      }).length;

      // Group documents by category
      const categoryMap = new Map<string, number>();
      documents.forEach((doc) => {
        if (doc.categories && doc.categories.length > 0) {
          doc.categories.forEach((category) => {
            categoryMap.set(category, (categoryMap.get(category) || 0) + 1);
          });
        } else {
          categoryMap.set(
            "Uncategorized",
            (categoryMap.get("Uncategorized") || 0) + 1
          );
        }
      });

      const documentsByCategory = Array.from(categoryMap.entries())
        .map(([category, count]) => ({ category, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

      // Generate upload trend data
      const uploadTrend = [];
      for (let i = days - 1; i >= 0; i--) {
        const date = new Date();
        date.setDate(date.getDate() - i);
        const dateStr = date.toISOString().split("T")[0];

        const count = documents.filter((doc) => {
          if (!doc.createdAt) return false;
          const uploadDate = new Date(doc.createdAt);
          return uploadDate.toISOString().split("T")[0] === dateStr;
        }).length;

        uploadTrend.push({
          date: dateStr,
          count,
        });
      }

      // Mock recent activity (in a real app, this would come from an activity log)
      const recentActivity = [
        {
          id: "1",
          type: "upload" as const,
          description: "Contract ABC-123.pdf uploaded",
          timestamp: new Date(Date.now() - 1000 * 60 * 30).toISOString(), // 30 minutes ago
          user: "John Doe",
        },
        {
          id: "2",
          type: "search" as const,
          description: 'Searched for "payment terms"',
          timestamp: new Date(Date.now() - 1000 * 60 * 60).toISOString(), // 1 hour ago
          user: "Jane Smith",
        },
        {
          id: "3",
          type: "download" as const,
          description: "Downloaded Project-Report.pdf",
          timestamp: new Date(Date.now() - 1000 * 60 * 60 * 2).toISOString(), // 2 hours ago
          user: "Mike Johnson",
        },
        {
          id: "4",
          type: "view" as const,
          description: "Viewed Agreement-XYZ.docx",
          timestamp: new Date(Date.now() - 1000 * 60 * 60 * 4).toISOString(), // 4 hours ago
          user: "Sarah Wilson",
        },
      ];

      const dashboardStats: DashboardStats = {
        totalDocuments: documents.length,
        totalOrganizations: organizationsResponse.length,
        totalProjects: projectsResponse.length,
        recentUploads,
        searchesThisWeek:
          analyticsResponse?.volume_over_time?.reduce(
            (sum: number, day: any) => sum + day.searches,
            0
          ) || 0,
        popularSearches: analyticsResponse?.top_searches?.slice(0, 5) || [
          { term: "contract", count: 45 },
          { term: "agreement", count: 32 },
          { term: "invoice", count: 28 },
          { term: "report", count: 21 },
          { term: "proposal", count: 18 },
        ],
        recentActivity,
        documentsByCategory,
        uploadTrend,
      };

      setStats(dashboardStats);
    } catch (err) {
      console.error("Failed to load dashboard data:", err);
      setError("Failed to load dashboard data");
    } finally {
      setLoading(false);
    }
  };

  const formatTimeAgo = (timestamp: string) => {
    const now = new Date();
    const time = new Date(timestamp);
    const diffInMinutes = Math.floor(
      (now.getTime() - time.getTime()) / (1000 * 60)
    );

    if (diffInMinutes < 60) {
      return `${diffInMinutes}m ago`;
    } else if (diffInMinutes < 1440) {
      return `${Math.floor(diffInMinutes / 60)}h ago`;
    } else {
      return `${Math.floor(diffInMinutes / 1440)}d ago`;
    }
  };

  const getActivityIcon = (type: string) => {
    switch (type) {
      case "upload":
        return <FileText className="h-4 w-4 text-blue-500" />;
      case "search":
        return <Search className="h-4 w-4 text-green-500" />;
      case "download":
        return <Download className="h-4 w-4 text-purple-500" />;
      case "view":
        return <Eye className="h-4 w-4 text-orange-500" />;
      default:
        return <Activity className="h-4 w-4 text-gray-500" />;
    }
  };

  if (loading) {
    return (
      <div className="max-w-7xl mx-auto p-6 space-y-6">
        <PageHeader
          icon={<BarChart3 className="h-6 w-6" />}
          title="Dashboard"
          description="Overview of your document management system"
        />
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {Array.from({ length: 4 }).map((_, i) => (
            <SkeletonCard key={i} />
          ))}
        </div>
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          {Array.from({ length: 4 }).map((_, i) => (
            <SkeletonCard key={i} />
          ))}
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="max-w-7xl mx-auto p-6">
        <PageHeader
          icon={<BarChart3 className="h-6 w-6" />}
          title="Dashboard"
          description="Overview of your document management system"
        />
        <Card>
          <CardContent className="p-6 text-center">
            <p className="text-red-600">{error}</p>
            <button
              onClick={loadDashboardData}
              className="mt-4 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
            >
              Retry
            </button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (!stats) return null;

  return (
    <div className="max-w-7xl mx-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <PageHeader
          icon={<BarChart3 className="h-6 w-6" />}
          title="Dashboard"
          description="Overview of your document management system"
        />
        <div className="flex gap-2">
          {(["7d", "30d", "90d"] as const).map((range) => (
            <button
              key={range}
              onClick={() => setTimeRange(range)}
              className={`px-3 py-1 text-sm rounded ${
                timeRange === range
                  ? "bg-blue-600 text-white"
                  : "bg-gray-100 text-gray-700 hover:bg-gray-200"
              }`}
            >
              {range === "7d"
                ? "7 days"
                : range === "30d"
                ? "30 days"
                : "90 days"}
            </button>
          ))}
        </div>
      </div>

      {/* Key Metrics */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">
                  Total Documents
                </p>
                <p className="text-2xl font-bold text-gray-900">
                  {stats.totalDocuments}
                </p>
              </div>
              <FileText className="h-8 w-8 text-blue-500" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">
                  Organizations
                </p>
                <p className="text-2xl font-bold text-gray-900">
                  {stats.totalOrganizations}
                </p>
              </div>
              <Building2 className="h-8 w-8 text-green-500" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">Projects</p>
                <p className="text-2xl font-bold text-gray-900">
                  {stats.totalProjects}
                </p>
              </div>
              <FolderOpen className="h-8 w-8 text-purple-500" />
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardContent className="p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm font-medium text-gray-600">
                  Recent Uploads
                </p>
                <p className="text-2xl font-bold text-gray-900">
                  {stats.recentUploads}
                </p>
                <p className="text-xs text-gray-500">Last {timeRange}</p>
              </div>
              <TrendingUp className="h-8 w-8 text-orange-500" />
            </div>
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Popular Searches */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Search className="h-5 w-5" />
              Popular Searches
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {stats.popularSearches.map((search, index) => (
                <div
                  key={search.term}
                  className="flex items-center justify-between"
                >
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-medium text-gray-600">
                      #{index + 1}
                    </span>
                    <span className="text-sm text-gray-900">{search.term}</span>
                  </div>
                  <Badge variant="outline">{search.count}</Badge>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Recent Activity */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Activity className="h-5 w-5" />
              Recent Activity
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {stats.recentActivity.map((activity) => (
                <div key={activity.id} className="flex items-start gap-3">
                  {getActivityIcon(activity.type)}
                  <div className="flex-1 min-w-0">
                    <p className="text-sm text-gray-900">
                      {activity.description}
                    </p>
                    <div className="flex items-center gap-2 mt-1">
                      {activity.user && (
                        <span className="text-xs text-gray-500">
                          {activity.user}
                        </span>
                      )}
                      <span className="text-xs text-gray-400">
                        {formatTimeAgo(activity.timestamp)}
                      </span>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Documents by Category */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <BarChart3 className="h-5 w-5" />
              Documents by Category
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {stats.documentsByCategory.map((category) => (
                <div
                  key={category.category}
                  className="flex items-center justify-between"
                >
                  <span className="text-sm text-gray-900">
                    {category.category}
                  </span>
                  <div className="flex items-center gap-2">
                    <div className="w-20 bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-blue-600 h-2 rounded-full"
                        style={{
                          width: `${
                            (category.count / stats.totalDocuments) * 100
                          }%`,
                        }}
                      />
                    </div>
                    <span className="text-sm font-medium text-gray-600 w-8 text-right">
                      {category.count}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        {/* Upload Trend */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <Calendar className="h-5 w-5" />
              Upload Trend
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {stats.uploadTrend.slice(-7).map((day) => (
                <div
                  key={day.date}
                  className="flex items-center justify-between"
                >
                  <span className="text-sm text-gray-600">
                    {new Date(day.date).toLocaleDateString("en-US", {
                      month: "short",
                      day: "numeric",
                    })}
                  </span>
                  <div className="flex items-center gap-2">
                    <div className="w-16 bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-green-600 h-2 rounded-full"
                        style={{
                          width: `${Math.max(
                            10,
                            (day.count /
                              Math.max(
                                ...stats.uploadTrend.map((d) => d.count)
                              )) *
                              100
                          )}%`,
                        }}
                      />
                    </div>
                    <span className="text-sm font-medium text-gray-600 w-6 text-right">
                      {day.count}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

