    };
  }, [viewLetter]);

  const [strategyPlanData, setStrategyPlanData] = useState<StrategyPlanResponse | null>(null);
  const [planDraft, setPlanDraft] = useState("");
  const [summaryPoints, setSummaryPoints] = useState<string[]>([]);
