    },
    {
      id: "billing",
      name: "Billing & Entitlements",
      icon: Lock,
      permissions: [
        { id: "billing.plan.view", name: "View Plans" },
        { id: "billing.plan.manage", name: "Manage Plans" },
        { id: "subscription.entitlement.manage", name: "Manage Entitlements" },
