                                                : ""
                                            }
                                            ${
                                              source
                                                ? `<tr>
                                                <td style="padding: 8px 0;">
                                                    <span style="color: #1e5bb8; font-weight: 600; font-size: 14px;">Source:</span>
                                                    <span style="color: #4a5568; font-size: 14px; margin-left: 5px;">${source}</span>
