</body>
</html>`;
    },
    []
  );

  const shareForm = useForm<ShareFormValues>({
    defaultValues: {
      subject: "Sharing document",
      message: buildDefaultMessage(),
      includeLinkedDocs: false,
      shareViaLink: true,
      attachFileToEmail: false,
      includeRefs: false,
      messageFormat: "html",
      registeredBy: "",
      distributionFor: "information",
    },
  });
  const includeRefsEnabled = shareForm.watch("includeRefs");
  const shareViaLinkEnabled = shareForm.watch("shareViaLink");
  const attachFileEnabled = shareForm.watch("attachFileToEmail");
  const [formPrefilled, setFormPrefilled] = React.useState(false);

  React.useEffect(() => {
    setFormPrefilled(false);
  }, [documentId]);

  React.useEffect(() => {
    if (document && !formPrefilled) {
      // Prioritize subject (letter subject) over filename for better context
      const docLabel =
        document.subject ||
        document.letterNo ||
        document.filename ||
        "Document";
      const currentValues = shareForm.getValues();
      const docRegisteredBy =
        (document as any)?.registeredBy ||
        (document as any)?.registered_by ||
        currentValues.registeredBy ||
        "";
      const distributionValue = currentValues.distributionFor || "information";
      shareForm.reset({
        ...currentValues,
        subject: `Sharing document: ${docLabel}`,
        message: buildDefaultMessage(docLabel),
        messageFormat: "html",
        registeredBy: docRegisteredBy,
        distributionFor: distributionValue,
      });
      setFormPrefilled(true);
    }
  }, [document, buildDefaultMessage, formPrefilled, shareForm]);

  React.useEffect(() => {
    if (ccRecipients.length && !showCc) {
      setShowCc(true);
    }
  }, [ccRecipients, showCc]);

  React.useEffect(() => {
    if (bccRecipients.length && !showBcc) {
      setShowBcc(true);
    }
  }, [bccRecipients, showBcc]);

  React.useEffect(() => {
    if (!includeRefsEnabled || refOptions.length === 0) {
      return;
    }
    setSelectedRefIds((prev) => {
      if (!prev.length) {
        return refOptions.map((opt) => opt.id);
      }
      const existing = new Set(prev);
      let changed = false;
      refOptions.forEach((opt) => {
        if (!existing.has(opt.id)) {
          existing.add(opt.id);
          changed = true;
        }
      });
      return changed ? Array.from(existing) : prev;
    });
  }, [includeRefsEnabled, refOptions]);

  // Utilities to add/remove emails with cross-list dedupe
  const addEmail = React.useCallback(
    (bucket: "to" | "cc" | "bcc", email: string) => {
      const val = email.trim().toLowerCase();
      if (!val) return;
      setToRecipients((prev) =>
        bucket === "to"
          ? Array.from(new Set([...prev, val]))
          : prev.filter((x) => x !== val)
      );
      setCcRecipients((prev) =>
        bucket === "cc"
          ? Array.from(new Set([...prev, val]))
          : prev.filter((x) => x !== val)
      );
      setBccRecipients((prev) =>
        bucket === "bcc"
          ? Array.from(new Set([...prev, val]))
          : prev.filter((x) => x !== val)
      );
    },
    []
  );
  const bulkAddEmails = React.useCallback(
    (bucket: "to" | "cc" | "bcc", emails: string[]) => {
      emails.forEach((entry) => addEmail(bucket, entry));
    },
    [addEmail]
  );

  // Recipient editor (field-scoped suggestion list)
  const RecipientEditor: React.FC<{
    label: string;
    field: "to" | "cc" | "bcc";
    values: string[];
    inputValue: string;
    setInputValue: (v: string) => void;
  }> = ({ label, field, values, inputValue, setInputValue }) => {
    const [open, setOpen] = React.useState(false);
    const [loading, setLoading] = React.useState(false);
    const [suggestions, setSuggestions] = React.useState<EmailSuggestion[]>([]);
    const initialLoadRef = React.useRef(false);

    const loadSuggestions = React.useCallback(
      async (query?: string) => {
        try {
          setLoading(true);
          const res = await emailService.resolveRecipients({
            query,
            include_representatives: recipientSource !== "parties",
            include_parties: recipientSource !== "representatives",
            organization_id: (document?.organization_id as any) || undefined,
            project_id: (document?.project_id as any) || undefined,
          });
          setSuggestions(res);
        } catch {
          setSuggestions([]);
        } finally {
          setLoading(false);
        }
      },
      [recipientSource, document?.organization_id, document?.project_id]
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
    React.useEffect(() => {
      initialLoadRef.current = false;
      if (open) {
        loadSuggestions(inputValue);
        initialLoadRef.current = true;
      }
    }, [recipientSource]);

    return (
      <div>
        <FormLabel>
          {label}
          {values.length > 0 ? (
            <span className="ml-2 text-xs text-muted-foreground">
              ({values.length})
            </span>
          ) : null}
        </FormLabel>
        <div className="mt-1 relative">
          <div className="flex flex-wrap gap-2 p-2 border rounded-md">
            {values.map((e) => (
              <span
                key={`${field}-${e}`}
                className="inline-flex items-center gap-1 bg-muted px-2 py-1 rounded text-sm"
              >
                {e}
                <button
                  type="button"
                  onClick={() => {
                    if (field === "to") {
                      setToRecipients((prev) => prev.filter((x) => x !== e));
                    } else if (field === "cc") {
                      setCcRecipients((prev) => prev.filter((x) => x !== e));
                    } else {
                      setBccRecipients((prev) => prev.filter((x) => x !== e));
                    }
                  }}
                  className="text-muted-foreground hover:text-foreground"
                  aria-label={`Remove ${e}`}
                >
                  <X className="w-3 h-3" />
                </button>
              </span>
            ))}
            <input
              className="flex-1 min-w-[200px] outline-none"
              placeholder="Type to search or paste emails (Enter or , to add)"
              value={inputValue}
              onChange={(ev) => {
                const v = ev.target.value;
                setInputValue(v);
                setOpen(true);
                loadSuggestions(v);
              }}
              onFocus={() => {
                setOpen(true);
                if (!initialLoadRef.current) {
                  loadSuggestions(inputValue);
                  initialLoadRef.current = true;
                }
              }}
              onBlur={() => {
                const val = inputValue.trim().replace(/,$/, "");
                if (val) {
                  addEmail(field, val);
                  setInputValue("");
                }
                setOpen(false);
              }}
              onPaste={(ev) => {
                const text = ev.clipboardData.getData("text");
                const parts = text
                  .split(/[\s,;]+/)
                  .map((s) => s.trim())
                  .filter(Boolean);
                if (parts.length > 1) {
                  ev.preventDefault();
                }
                parts.forEach((p) => addEmail(field, p));
                setInputValue("");
                setOpen(false);
              }}
              onKeyDown={(ev) => {
                if (ev.key === "Enter" || ev.key === ",") {
                  ev.preventDefault();
                  const val = inputValue.trim().replace(/,$/, "");
                  if (val) {
                    addEmail(field, val);
                    setInputValue("");
                    setOpen(false);
                  }
                }
              }}
            />
          </div>
          {open && (
            <div className="absolute z-50 mt-1 w-full bg-white border rounded-md shadow">
              <div className="max-h-56 overflow-auto">
                {loading && (
                  <div className="p-2 text-sm text-muted-foreground">
                    Loading...
                  </div>
                )}
                {!loading && suggestions.length === 0 && (
                  <div className="p-2 text-sm text-muted-foreground">
                    No suggestions found.
                  </div>
                )}
                {suggestions.map((s) => (
                  <button
                    type="button"
                    key={`${field}-sugg-${s.email}`}
                    className="w-full text-left px-3 py-2 hover:bg-muted/50"
                    onMouseDown={(e) => e.preventDefault()}
                    onClick={() => {
                      addEmail(field, s.email);
                      setInputValue("");
                      setOpen(false);
                    }}
                  >
                    <div className="font-medium">{s.name}</div>
                    <div className="text-sm text-muted-foreground">
                      {s.email}
                    </div>
                    {s.organization && (
                      <div className="text-xs text-muted-foreground">
                        {s.organization}
                      </div>
                    )}
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    );
  };

  const shareFormInstance = shareForm;

  const handleShareSubmit = async (values: ShareFormValues) => {
    if (!document?._id) {
      toast.error("Document ID not available");
      return;
    }
    try {
      setIsSending(true);
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!values.shareViaLink && !values.attachFileToEmail) {
        toast.error("Choose Share via link, Attach file to email, or both");
        return;
      }

      const rawEmails = [
        ...toRecipients,
        toInput,
        ...ccRecipients,
        ccInput,
        ...bccRecipients,
        bccInput,
      ]
        .map((e) => (e || "").trim().toLowerCase())
        .filter(Boolean);
      const invalid = rawEmails.filter((e) => !emailRegex.test(e));
      if (invalid.length) {
        toast.error(`Invalid email(s): ${invalid.join(", ")}`);
        return;
      }

      const uniqueTo = Array.from(
        new Set(
          [...toRecipients, toInput]
            .map((e) => (e || "").trim().toLowerCase())
            .filter((e) => e && emailRegex.test(e))
        )
      );
      const uniqueCc = Array.from(
        new Set(
          [...ccRecipients, ccInput]
            .map((e) => (e || "").trim().toLowerCase())
            .filter((e) => e && emailRegex.test(e))
        )
      );
      const uniqueBcc = Array.from(
        new Set(
          [...bccRecipients, bccInput]
            .map((e) => (e || "").trim().toLowerCase())
            .filter((e) => e && emailRegex.test(e))
        )
      );

      if (uniqueTo.length === 0) {
        toast.error("Add at least one recipient in To");
        return;
      }

      const activeRefIds = values.includeRefs
        ? selectedRefIds.length
          ? selectedRefIds
          : refOptions.map((opt) => opt.id)
        : [];

      const request = {
        to: uniqueTo,
        cc: uniqueCc,
        bcc: uniqueBcc,
        subject: values.subject,
        message: values.message,
        document_id: document._id!,
        include_linked_documents: values.includeLinkedDocs,
        share_via_link: values.shareViaLink,
        attach_file_to_email: values.attachFileToEmail,
        include_refs: values.includeRefs,
        reference_ids: activeRefIds,
        email_format: values.messageFormat,
        registered_by: values.registeredBy?.trim() || undefined,
        distribution_for: values.distributionFor,
      };

      const response = await emailService.shareDocument(request);
      toast.success("Document shared successfully", {
        description: `Recipients: ${uniqueTo.length}${
          uniqueCc.length ? ` (+CC ${uniqueCc.length})` : ""
        }. ${
          response.delivery_methods?.share_via_link ? "Link shared" : "No link"
        }; ${response.attachments_count} file(s) attached. Returning to document...`,
      });

      // Reset and navigate back
      shareFormInstance.reset();
      setToRecipients([]);
      setCcRecipients([]);
      setBccRecipients([]);
      setToInput("");
      setCcInput("");
      setBccInput("");
      setSelectedRefIds([]);

      navigate(`/documentviewer/${document._id}`);
    } catch (error: any) {
      console.error("Error sharing document:", error);
      toast.error("Failed to share document", {
        description: error?.message || "Please try again later",
      });
    } finally {
      setIsSending(false);
    }
  };

  if (isLoading) {
    return (
      <div className="p-6">
        <div className="max-w-5xl mx-auto space-y-4">
          <div className="h-9 w-48 rounded bg-muted animate-pulse" />
          <div className="rounded-lg border bg-white p-6">
            <div className="h-5 w-64 rounded bg-muted animate-pulse" />
            <div className="mt-6 grid gap-4 md:grid-cols-2">
              <div className="h-10 rounded bg-muted animate-pulse" />
              <div className="h-10 rounded bg-muted animate-pulse" />
              <div className="h-28 rounded bg-muted animate-pulse md:col-span-2" />
            </div>
          </div>
        </div>
      </div>
    );
  }

  if (!document) {
    return (
      <div className="p-6">
        <div className="max-w-5xl mx-auto rounded-lg border bg-white p-8 text-center">
          <AlertTriangle className="mx-auto mb-3 h-8 w-8 text-red-600" />
          <h1 className="text-lg font-semibold">Document not available</h1>
          <p className="mx-auto mt-2 max-w-md text-sm text-muted-foreground">
            {loadError || "The document could not be found or you do not have access."}
          </p>
          <div className="mt-6 flex justify-center gap-3">
            <Button variant="outline" onClick={() => navigate(-1)}>
              Back
            </Button>
            <Button onClick={() => setRetryCounter((value) => value + 1)}>
              <RefreshCw className="mr-2 h-4 w-4" />
              Retry
            </Button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6">
      <div className="max-w-5xl mx-auto space-y-6">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="icon" asChild>
            <Link to={`/documentviewer/${document._id}`}>
              <ArrowLeft className="h-5 w-5" />
            </Link>
          </Button>
          <div>
            <h1 className="text-xl font-semibold">Share Document</h1>
            <p className="text-sm text-muted-foreground">{document.filename}</p>
          </div>
        </div>

        <div className="rounded-lg border bg-white">
          <div className="p-6">
            <Form {...shareFormInstance}>
              <form
                onSubmit={shareFormInstance.handleSubmit(handleShareSubmit)}
                className="space-y-5"
              >
                {/* Recipient source selector */}
                <div className="space-y-2">
                  <FormLabel>Recipient Source</FormLabel>
                  <div className="flex items-center gap-6">
                    <label className="flex items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="recipient_source"
                        value="representatives"
                        checked={recipientSource === "representatives"}
                        onChange={() => {
                          setRecipientSource("representatives");
                          localStorage.setItem(
                            "share_recipient_source",
                            "representatives"
                          );
                        }}
                      />
                      Representatives
                    </label>
                    <label className="flex items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="recipient_source"
                        value="parties"
                        checked={recipientSource === "parties"}
                        onChange={() => {
                          setRecipientSource("parties");
                          localStorage.setItem(
                            "share_recipient_source",
                            "parties"
                          );
                        }}
                      />
                      Parties
                    </label>
                    <label className="flex items-center gap-2 text-sm">
                      <input
                        type="radio"
                        name="recipient_source"
                        value="both"
                        checked={recipientSource === "both"}
                        onChange={() => {
                          setRecipientSource("both");
                          localStorage.setItem(
                            "share_recipient_source",
                            "both"
                          );
                        }}
                      />
                      Both
                    </label>
                  </div>
                </div>

                {/* Recipients */}
                <div className="space-y-3">
                  {/* Group selection */}
                  {groups.length > 0 && (
                    <div className="space-y-2">
                      <Label>Groups</Label>
                      <div className="border rounded-md p-2 max-h-40 overflow-auto">
                        {groups.map((g) => (
                          <label
                            key={g._id}
                            className="flex items-center gap-2 text-sm py-1"
                          >
                            <input
                              type="checkbox"
                              checked={selectedGroupIds.includes(g._id)}
                              onChange={(e) => {
                                const checked = e.target.checked;
                                setSelectedGroupIds((prev) =>
                                  checked
                                    ? Array.from(new Set([...prev, g._id]))
                                    : prev.filter((id) => id !== g._id)
                                );
                              }}
                            />
                            <span className="font-medium">{g.name}</span>
                            <span className="text-xs text-muted-foreground">
                              {(g.category || "").toString()} •{" "}
                              {g.emails?.length || 0} member(s)
                            </span>
                          </label>
                        ))}
                      </div>
                      <div className="flex flex-wrap items-center gap-3">
                        <div className="flex items-center gap-2 text-xs text-muted-foreground">
                          <span>Add selected groups to:</span>
                          <select
                            className="rounded border px-2 py-1 text-xs"
                            value={groupTarget}
                            onChange={(e) =>
                              setGroupTarget(
                                e.target.value as "to" | "cc" | "bcc"
                              )
                            }
                          >
                            <option value="to">To</option>
                            <option value="cc">CC</option>
                            <option value="bcc">BCC</option>
                          </select>
                        </div>
                        <Button
                          type="button"
                          variant="outline"
                          size="sm"
                          onClick={() => {
                            const selected = groups.filter((g) =>
                              selectedGroupIds.includes(g._id)
                            );
                            const emails = Array.from(
                              new Set(selected.flatMap((g) => g.emails || []))
                            );
                            if (!emails.length) {
                              toast.message("Select at least one group", {
                                description:
                                  "Choose a group before attempting to add recipients.",
                              });
                              return;
                            }
                            bulkAddEmails(groupTarget, emails);
                            toast.success(
                              `Added ${emails.length} recipient${
                                emails.length > 1 ? "s" : ""
                              } to ${groupTarget.toUpperCase()}`
                            );
                          }}
                        >
                          Apply Group Recipients
                        </Button>
                      </div>
                    </div>
                  )}
                  <RecipientEditor
                    label="To"
                    field="to"
                    values={toRecipients}
                    inputValue={toInput}
                    setInputValue={setToInput}
                  />
                  <div className="flex flex-wrap items-center gap-4 text-sm">
                    {!showCc && (
                      <button
                        type="button"
                        className="text-primary hover:underline"
                        onClick={() => setShowCc(true)}
                      >
                        + Add CC{" "}
                        {ccRecipients.length ? `(${ccRecipients.length})` : ""}
                      </button>
                    )}
                    {!showBcc && (
                      <button
                        type="button"
                        className="text-primary hover:underline"
                        onClick={() => setShowBcc(true)}
                      >
                        + Add BCC{" "}
                        {bccRecipients.length
                          ? `(${bccRecipients.length})`
                          : ""}
                      </button>
                    )}
                  </div>
                  {!showCc && ccRecipients.length > 0 && (
                    <div className="text-xs text-muted-foreground pl-1">
                      CC hidden • {ccRecipients.length} recipient
                      {ccRecipients.length > 1 ? "s" : ""}
                    </div>
                  )}
                  {showCc && (
                    <div className="space-y-2">
                      <div className="flex items-center justify-between text-xs text-muted-foreground">
                        <span>CC Recipients</span>
                        <button
                          type="button"
                          className="text-primary hover:underline"
                          onClick={() => setShowCc(false)}
                        >
                          Hide CC
                        </button>
                      </div>
                      <RecipientEditor
                        label="CC"
                        field="cc"
                        values={ccRecipients}
                        inputValue={ccInput}
                        setInputValue={setCcInput}
                      />
                    </div>
                  )}
                  {!showBcc && bccRecipients.length > 0 && (
                    <div className="text-xs text-muted-foreground pl-1">
                      BCC hidden • {bccRecipients.length} recipient
                      {bccRecipients.length > 1 ? "s" : ""}
                    </div>
                  )}
                  {showBcc && (
                    <div className="space-y-2">
                      <div className="flex items-center justify-between text-xs text-muted-foreground">
                        <span>BCC Recipients</span>
                        <button
                          type="button"
                          className="text-primary hover:underline"
                          onClick={() => setShowBcc(false)}
                        >
                          Hide BCC
                        </button>
                      </div>
                      <RecipientEditor
                        label="BCC"
                        field="bcc"
                        values={bccRecipients}
                        inputValue={bccInput}
                        setInputValue={setBccInput}
                      />
                    </div>
                  )}
                </div>

                <div className="text-sm text-muted-foreground">
                  Recipients selected: {recipientsCount}
                </div>

                {/* Delivery options */}
                <div className="space-y-3">
                  <div>
                    <FormLabel>Delivery options</FormLabel>
                    <p className="text-sm text-muted-foreground">
                      Select one or both delivery methods for this share.
                    </p>
                  </div>
                  <div className="grid gap-3 md:grid-cols-2">
                    <FormField
                      control={shareFormInstance.control}
                      name="shareViaLink"
                      render={({ field }) => (
                        <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4">
                          <FormControl>
                            <Checkbox
                              checked={field.value}
                              onCheckedChange={field.onChange}
                            />
                          </FormControl>
                          <div className="space-y-1 leading-none">
                            <FormLabel>Share via link</FormLabel>
                            <p className="text-sm text-muted-foreground">
                              Email a secure public download link that does not
                              require recipient login.
                            </p>
                          </div>
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={shareFormInstance.control}
                      name="attachFileToEmail"
                      render={({ field }) => (
                        <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4">
                          <FormControl>
                            <Checkbox
                              checked={field.value}
                              onCheckedChange={field.onChange}
                            />
                          </FormControl>
                          <div className="space-y-1 leading-none">
                            <FormLabel>Attach file to email</FormLabel>
                            <p className="text-sm text-muted-foreground">
                              Attach the primary document. Large files may need
                              the link option instead.
                            </p>
                          </div>
                        </FormItem>
                      )}
                    />
                  </div>
                  {!shareViaLinkEnabled && !attachFileEnabled && (
                    <p className="text-sm text-destructive">
                      Choose at least one delivery option.
                    </p>
                  )}
                </div>

                {/* Include refs */}
                <FormField
                  control={shareFormInstance.control}
                  name="includeRefs"
                  render={({ field }) => (
                    <FormItem className="flex flex-col gap-2 rounded-md border p-4">
                      <div className="flex flex-row items-start space-x-3">
                        <FormControl>
                          <Checkbox
                            checked={field.value}
                            onCheckedChange={(checked) => {
                              const nextValue = !!checked;
                              field.onChange(nextValue);
                              if (nextValue) {
                                setSelectedRefIds((prev) =>
                                  prev.length
                                    ? prev
                                    : refOptions.map((opt) => opt.id)
                                );
                              } else {
                                setSelectedRefIds([]);
                              }
                            }}
                          />
                        </FormControl>
                        <div className="space-y-1 leading-none">
                          <FormLabel>Include reference letters</FormLabel>
                          <p className="text-sm text-muted-foreground">
                            Select reference letters to include their share
                            links.
                          </p>
                        </div>
                      </div>

                      {field.value && (
                        <div className="mt-2 max-h-40 overflow-auto space-y-2">
                          {refOptions.length === 0 ? (
                            <div className="text-sm text-muted-foreground">
                              No references found.
                            </div>
                          ) : (
                            refOptions.map((opt) => {
                              const checked = selectedRefIds.includes(opt.id);
                              return (
                                <label
                                  key={opt.id}
                                  className="flex items-center gap-2 text-sm"
                                >
                                  <input
                                    type="checkbox"
                                    checked={checked}
                                    onChange={(e) => {
                                      const isOn = e.target.checked;
                                      setSelectedRefIds((prev) =>
                                        isOn
                                          ? Array.from(
                                              new Set([...prev, opt.id])
                                            )
                                          : prev.filter((x) => x !== opt.id)
                                      );
                                    }}
                                  />
                                  {opt.label}
                                </label>
                              );
                            })
                          )}
                        </div>
                      )}
                    </FormItem>
                  )}
                />

                {/* Message format */}
                <FormField
                  control={shareFormInstance.control}
                  name="messageFormat"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Message format</FormLabel>
                      <FormControl>
                        <div className="flex items-center gap-6">
                          <label className="flex items-center gap-2 text-sm">
                            <input
                              type="radio"
                              name="message_format"
                              value="text"
                              checked={field.value === "text"}
                              onChange={() => field.onChange("text")}
                            />
                            Plain text
                          </label>
                          <label className="flex items-center gap-2 text-sm">
                            <input
                              type="radio"
                              name="message_format"
                              value="html"
                              checked={field.value === "html"}
                              onChange={() => field.onChange("html")}
                            />
                            HTML (formatted)
                          </label>
                        </div>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Subject */}
                <FormField
                  control={shareFormInstance.control}
                  name="subject"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Subject</FormLabel>
                      <FormControl>
                        <Input
                          placeholder="Email subject"
                          {...field}
                          required
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={shareFormInstance.control}
                  name="registeredBy"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Registered by</FormLabel>
                      <FormControl>
                        <Input
                          placeholder='Name of the registering user (e.g., "John Doe")'
                          {...field}
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                <FormField
                  control={shareFormInstance.control}
                  name="distributionFor"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Distributed for</FormLabel>
                      <FormControl>
                        <div className="flex items-center gap-6">
                          <label className="flex items-center gap-2 text-sm">
                            <input
                              type="radio"
                              name="distribution_for"
                              value="information"
                              checked={field.value === "information"}
                              onChange={() => field.onChange("information")}
                            />
                            Information
                          </label>
                          <label className="flex items-center gap-2 text-sm">
                            <input
                              type="radio"
                              name="distribution_for"
                              value="answer"
                              checked={field.value === "answer"}
                              onChange={() => field.onChange("answer")}
                            />
                            Answer
                          </label>
                        </div>
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Message */}
                <FormField
                  control={shareFormInstance.control}
                  name="message"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel>Message</FormLabel>
                      <p className="text-xs text-muted-foreground">
                        Supports plain text or basic HTML based on the selected
                        format.
                      </p>
                      <FormControl>
                        <Textarea
                          placeholder="Enter your message"
                          {...field}
                          rows={8}
                          required
                        />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />

                {/* Link enclosures */}
                <FormField
                  control={shareFormInstance.control}
                  name="includeLinkedDocs"
                  render={({ field }) => (
                    <FormItem className="flex flex-row items-start space-x-3 space-y-0 rounded-md border p-4">
                      <FormControl>
                        <Checkbox
                          checked={field.value}
                          onCheckedChange={field.onChange}
                        />
                      </FormControl>
                      <div className="space-y-1 leading-none">
                        <FormLabel>Link enclosures</FormLabel>
                        <p className="text-sm text-muted-foreground">
                          Include links to all enclosures in the email (
                          {enclosureCount} documents)
                        </p>
                      </div>
                    </FormItem>
                  )}
                />

                <div className="flex items-center justify-between pt-2">
                  <Button variant="outline" type="button" asChild>
                    <Link to={`/documentviewer/${document._id}`}>Cancel</Link>
                  </Button>
                  <Button type="submit" disabled={isSending}>
                    {isSending ? (
                      <>
                        <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                        Sending...
                      </>
                    ) : (
                      <>
                        <Mail className="mr-2 h-4 w-4" />
                        Send Email
                      </>
                    )}
                  </Button>
                </div>
              </form>
            </Form>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ShareDocumentPage;

import React, { useState, ChangeEvent, useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Switch } from "@/components/ui/switch";
import { useNavigate } from "react-router-dom";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Upload,
  X,
  FileText,
  Image,
  RefreshCw,
  Link as LinkIcon,
} from "lucide-react";
import { useToast } from "@/hooks/use-toast";
import enhancedApi, {
  BulkUploadStatus,
  Organization as OrgModel,
} from "@/services/enhanced-api";

interface UploadFile {
  id: string;
  file: File;
  name: string;
  size: number;
  type: string;
}

interface Organization {
  _id: string;
  name: string;
}

interface Project {
  _id: string;
  name: string;
  organization_id: string;
}

type FileWithRelativePath = File & { webkitRelativePath?: string };

const UploadPage: React.FC = () => {
  const navigate = useNavigate();
  const { toast } = useToast();

  // Single upload states
  const [files, setFiles] = useState<UploadFile[]>([]);
  const [uploadType, setUploadType] = useState<"incoming" | "outgoing">(
    "incoming"
  );
  const [letterNo, setLetterNo] = useState("");
  const [organizationId, setOrganizationId] = useState("");
  const [projectId, setProjectId] = useState("");
  const [letterDate, setLetterDate] = useState("");
  const [subject, setSubject] = useState("");
  const [from, setFrom] = useState("");
  const [to, setTo] = useState("");
  const [tags, setTags] = useState<string[]>([]);
  const [subTags, setSubTags] = useState<string[]>([]);
  const [status, setStatus] = useState("");
  const [ocrEnabled, setOcrEnabled] = useState(true);
  const [compressionEnabled, setCompressionEnabled] = useState(false);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [projects, setProjects] = useState<Project[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);
  const [pathStructure, setPathStructure] = useState<string>("");
  const [bulkOrganizationId, setBulkOrganizationId] = useState<string>("");
  const [bulkProjectId, setBulkProjectId] = useState<string>("");
  const [bulkPathStructure, setBulkPathStructure] =
    useState<string>("generating-path...");
  const [bulkFolderStructurePreview, setBulkFolderStructurePreview] = useState<
    string[]
  >([]);
  const [isFolderDragOver, setIsFolderDragOver] = useState(false);

  // Controls
  const [uploading, setUploading] = useState<boolean>(false);

  // Bulk upload states
  const [bulkFiles, setBulkFiles] = useState<FileWithRelativePath[]>([]);
  const [csvFile, setCsvFile] = useState<File | null>(null);
  const [bulkJobId, setBulkJobId] = useState<string | null>(null);
  const [bulkStatus, setBulkStatus] = useState<BulkUploadStatus | null>(null);
  const [bulkUploading, setBulkUploading] = useState<boolean>(false);
  const pollRef = useRef<number | null>(null);
  const folderInputRef = useRef<HTMLInputElement | null>(null);

  // Normalize date for API (YYYY-MM-DD)
  const formatDateForApi = (d: string) => {
    if (!d) return new Date().toISOString().slice(0, 10);
    try {
      const dt = new Date(d);
      if (!isNaN(dt.getTime())) return dt.toISOString().slice(0, 10);
    } catch {}
    return new Date().toISOString().slice(0, 10);
  };

  // Add this utility function near the top of the file
  const shortenName = (name: string, maxLength: number = 10): string => {
    return (
      name
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-") // Replace special chars with hyphens
        .replace(/(^-+|-+$)/g, "") // Trim hyphens
        .substring(0, maxLength) // Truncate
        .replace(/-+/g, "-") // Remove consecutive hyphens
        .replace(/(^-|-$)/g, "") || "untitled"
    ); // Fallback
  };

  // Fetch organizations and projects
  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      try {
        const orgs = await enhancedApi.getOrganizations();
        // Map to local Organization interface
        const mappedOrgs: Organization[] = (orgs as OrgModel[]).map((o) => ({
          _id: (o as any)._id,
          name: (o as any).name,
        }));
        setOrganizations(mappedOrgs);

        const projs = await enhancedApi.getProjects();
        const mappedProjs: Project[] = projs.map((p: any) => ({
          _id: p._id,
          name: p.name,
          organization_id: p.organization_id,
        }));
        setProjects(mappedProjs);
      } catch (err: any) {
        setError(err?.message || "Failed to load organizations/projects");
        toast({
          title: "Error",
          description: err?.message || "Failed to load organizations/projects",
          variant: "destructive",
        });
      } finally {
        setIsLoading(false);
      }
    };
    fetchData();
  }, []);

  // Update pathStructure preview when org/project changes
  useEffect(() => {
    if (
      organizationId &&
      projectId &&
      organizations.length &&
      projects.length
    ) {
      const org = organizations.find((o) => o._id === organizationId);
      const project = projects.find((p) => p._id === projectId);
      if (org && project) {
        setPathStructure(
          `${shortenName(org.name)}/${shortenName(project.name)}/`
        );
      } else {
        setPathStructure("generating-path...");
      }
    } else {
      setPathStructure("generating-path...");
    }
  }, [organizationId, projectId, organizations, projects]);

  useEffect(() => {
    if (
      bulkOrganizationId &&
      bulkProjectId &&
      organizations.length &&
      projects.length
    ) {
      const org = organizations.find((o) => o._id === bulkOrganizationId);
      const project = projects.find((p) => p._id === bulkProjectId);
      if (org && project) {
        setBulkPathStructure(
          `${shortenName(org.name)}/${shortenName(project.name)}/`
        );
        return;
      }
    }
    setBulkPathStructure("generating-path...");
  }, [bulkOrganizationId, bulkProjectId, organizations, projects]);

  useEffect(() => {
    if (folderInputRef.current) {
      folderInputRef.current.setAttribute("webkitdirectory", "");
      folderInputRef.current.setAttribute("directory", "");
      folderInputRef.current.setAttribute("mozdirectory", "");
    }
  }, []);

  const handleBulkOrganizationChange = (value: string) => {
    setBulkOrganizationId(value);
    setBulkProjectId("");
  };

  const processFolderSelection = (fileList: FileList | File[]) => {
    const incomingFiles = Array.from(fileList) as FileWithRelativePath[];
    if (!incomingFiles.length) {
      setBulkFiles([]);
      setBulkFolderStructurePreview([]);
      setIsFolderDragOver(false);
      return;
    }

    // Check if this is a folder upload by looking for webkitRelativePath
    const hasRelativePaths = incomingFiles.some(
      (file) => file.webkitRelativePath
    );
    const filesMissingRelativePath = incomingFiles.some(
      (file) => !file.webkitRelativePath
    );

    // If some files have relative paths and some don't, it's likely a mixed selection
    if (hasRelativePaths && filesMissingRelativePath) {
      setBulkFiles([]);
      setBulkFolderStructurePreview([]);
      setIsFolderDragOver(false);
      toast({
        title: "Mixed File Selection",
        description:
          "Please select either individual files or a complete folder, not both.",
        variant: "destructive",
      });
      return;
    }

    // If no files have relative paths, this might be individual file selection or unsupported browser
    if (!hasRelativePaths) {
      // Check if user is trying to upload a folder but browser doesn't support it
      if (incomingFiles.length > 10) {
        // Heuristic: many files might indicate folder attempt
        toast({
          title: "Folder Upload Not Supported",
          description:
            "Your browser doesn't support folder uploads. Please use Chrome, Edge, or Firefox, or compress the folder into a ZIP file.",
          variant: "destructive",
        });
      } else {
        toast({
          title: "Individual Files Detected",
          description:
            "For bulk upload, please select a folder or use the regular upload tab for individual files.",
          variant: "destructive",
        });
      }
      setBulkFiles([]);
      setBulkFolderStructurePreview([]);
      setIsFolderDragOver(false);
      return;
    }

    // Sort files by their relative path for consistent processing
    const sortedFiles = [...incomingFiles].sort((a, b) => {
      const aPath = (a.webkitRelativePath || a.name).toLowerCase();
      const bPath = (b.webkitRelativePath || b.name).toLowerCase();
      return aPath.localeCompare(bPath);
    });

    // Validate that all files come from a single root folder
    const rootFolders = new Set<string>();
    sortedFiles.forEach((file) => {
      const relativePath = file.webkitRelativePath || "";
      if (relativePath.includes("/")) {
        const topLevel = relativePath.split("/")[0];
        rootFolders.add(topLevel);
      } else {
        rootFolders.add("__root__");
      }
    });

    if (rootFolders.size > 1) {
      setBulkFiles([]);
      setBulkFolderStructurePreview([]);
      setIsFolderDragOver(false);
      toast({
        title: "Multiple Root Folders",
        description:
          "Please select a single folder. Multiple root folders detected in your selection.",
        variant: "destructive",
      });
      return;
    }

    // Filter out system files and hidden files
    const filteredFiles = sortedFiles.filter((file) => {
      const fileName = file.name.toLowerCase();
      const relativePath = file.webkitRelativePath || "";

      // Skip system files
      if (
        fileName.startsWith(".") ||
        fileName === "thumbs.db" ||
        fileName === "desktop.ini"
      ) {
        return false;
      }

      // Skip files in hidden directories
      if (relativePath.includes("/.") || relativePath.includes("\\.")) {
        return false;
      }

      return true;
    });

    if (filteredFiles.length === 0) {
      setBulkFiles([]);
      setBulkFolderStructurePreview([]);
      setIsFolderDragOver(false);
      toast({
        title: "No Valid Files",
        description:
          "No valid files found in the selected folder. Please ensure the folder contains document files.",
        variant: "destructive",
      });
      return;
    }

    // Generate folder structure preview
    const folderPaths = new Set<string>();
    filteredFiles.forEach((file) => {
      const relativePath = file.webkitRelativePath || "";
      if (relativePath.includes("/")) {
        const folderPath = relativePath.substring(
          0,
          relativePath.lastIndexOf("/")
        );
        folderPaths.add(folderPath);
      } else {
        folderPaths.add("(root)");
      }
    });

    const folderPreview = Array.from(folderPaths)
      .filter(Boolean)
      .sort((a, b) => {
        // Sort with root first, then alphabetically
        if (a === "(root)") return -1;
        if (b === "(root)") return 1;
        return a.localeCompare(b);
      });

    setBulkFiles(filteredFiles);
    setBulkFolderStructurePreview(
      folderPreview.length ? folderPreview : ["(root)"]
    );
    setIsFolderDragOver(false);

    // Clear the input value to allow re-selection of the same folder
    if (folderInputRef.current) {
      folderInputRef.current.value = "";
    }

    toast({
      title: "Folder Selected",
      description: `Successfully selected ${filteredFiles.length} files from the folder structure.`,
    });
  };

  const handleFolderChange = (event: ChangeEvent<HTMLInputElement>) => {
    if (!event.target.files) return;
    processFolderSelection(event.target.files);
  };

  const handleFolderDrop = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.stopPropagation();
    setIsFolderDragOver(false);

    const { files, items } = event.dataTransfer;

    // Check if items are available (better folder detection)
    if (items && items.length > 0) {
      // Check if any item is a directory
      const hasDirectories = Array.from(items).some(
        (item) =>
          item.kind === "file" &&
          item.webkitGetAsEntry &&
          item.webkitGetAsEntry()?.isDirectory
      );

      if (hasDirectories) {
        // Handle directory drop using webkitGetAsEntry API
        handleDirectoryDrop(items);
        return;
      }
    }

    // Fallback to regular file handling
    if (files && files.length) {
      processFolderSelection(files);
    }
  };

  const handleDirectoryDrop = async (items: DataTransferItemList) => {
    const files: FileWithRelativePath[] = [];

    const processEntry = async (entry: any, path = "") => {
      if (entry.isFile) {
        return new Promise<void>((resolve) => {
          entry.file((file: File) => {
            const fileWithPath = file as FileWithRelativePath;
            fileWithPath.webkitRelativePath = path + file.name;
            files.push(fileWithPath);
            resolve();
          });
        });
      } else if (entry.isDirectory) {
        const dirReader = entry.createReader();
        return new Promise<void>((resolve) => {
          dirReader.readEntries(async (entries: any[]) => {
            for (const childEntry of entries) {
              await processEntry(childEntry, path + entry.name + "/");
            }
            resolve();
          });
        });
      }
    };

    try {
      for (let i = 0; i < items.length; i++) {
        const item = items[i];
        if (item.kind === "file") {
          const entry = item.webkitGetAsEntry();
          if (entry) {
            await processEntry(entry);
          }
        }
      }

      if (files.length > 0) {
        processFolderSelection(files);
      }
    } catch (error) {
      console.error("Error processing directory drop:", error);
      toast({
        title: "Folder Drop Error",
        description:
          "Failed to process the dropped folder. Please try selecting the folder using the file picker.",
        variant: "destructive",
      });
    }
  };

  const handleFolderDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "copy";
    if (!isFolderDragOver) {
      setIsFolderDragOver(true);
    }
  };

  const handleFolderDragLeave = () => {
    if (isFolderDragOver) {
      setIsFolderDragOver(false);
    }
  };

  const handleFileChange = (e: ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files) return;
    const selectedFiles = Array.from(e.target.files);
    const newFiles = selectedFiles.map((file) => ({
      id: Math.random().toString(36).substr(2, 9),
      file,
      name: file.name,
      size: file.size,
      type: file.type,
    }));
    setFiles((prev) => [...prev, ...newFiles]);
  };

  const handleUpload = async () => {
    if (files.length === 0) {
      toast({
        title: "Warning",
        description: "Please select files to upload.",
        variant: "destructive",
      });
      return;
    }
    if (!organizationId || !projectId) {
      toast({
        title: "Warning",
        description: "Please select organization and project",
        variant: "destructive",
      });
      return;
    }

    try {
      setUploading(true);
      let firstDocId: string | null = null;

      // Upload sequentially to match backend single-file contract
      for (let i = 0; i < files.length; i++) {
        const f = files[i].file;
        const autoLetter =
          letterNo || `AUTO-${new Date().getFullYear()}-${Date.now()}-${i + 1}`;

        const doc = await enhancedApi.uploadDocument({
          file: f,
          organization_id: organizationId,
          project_id: projectId,
          uploadType,
          letterNo: autoLetter,
          date: formatDateForApi(letterDate),
          subject,
          from,
          to,
          tags,
          subTags,
          status: status || "draft",
          ocrEnabled,
          compressionEnabled,
        });

        const id = (doc as any)?._id || (doc as any)?.id;
        if (!firstDocId && id) firstDocId = id;
      }

      if (firstDocId) {
        navigate(`/documentviewer/${firstDocId}`);
      }

      toast({
        title: "Success",
        description: `Uploaded ${files.length} file${
          files.length > 1 ? "s" : ""
        } successfully.`,
      });

      // Reset
      setFiles([]);
      setLetterNo("");
      setOcrEnabled(false);
      setCompressionEnabled(false);
    } catch (error: any) {
      toast({
        title: "Error",
        description: error?.message || "Upload failed",
        variant: "destructive",
      });
    } finally {
      setUploading(false);
    }
  };

  const removeFile = (id: string) => {
    setFiles((prev) => prev.filter((f) => f.id !== id));
  };

  const formatFileSize = (bytes: number) => {
    if (bytes === 0) return "0 Bytes";
    const k = 1024;
    const sizes = ["Bytes", "KB", "MB", "GB", "TB"];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + " " + sizes[i];
  };

  if (isLoading) return <div>Loading...</div>;
  if (error) return <div>Error: {error}</div>;

  return (
    <div className="container mx-auto py-8 animate-fade-in">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold">Upload Documents</h1>
      </div>

      <Tabs defaultValue="upload" className="mb-8">
        <TabsList className="grid w-full md:w-[400px] grid-cols-3">
          <TabsTrigger value="upload">Upload</TabsTrigger>
          <TabsTrigger value="url">From URL</TabsTrigger>
          <TabsTrigger value="bulk">Bulk Upload</TabsTrigger>
        </TabsList>

        {/* Single Upload */}
        <TabsContent value="upload" className="mt-6">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <Card className="md:col-span-2">
              <CardHeader>
                <CardTitle>Upload Files</CardTitle>
                <CardDescription>
                  Drag and drop files or click to browse
                </CardDescription>
              </CardHeader>
              <CardContent>
                <div
                  className="border-2 border-dashed rounded-lg p-12 text-center hover:bg-accent transition-colors cursor-pointer"
                  onClick={() => document.getElementById("fileInput")?.click()}
                >
                  <input
                    type="file"
                    id="fileInput"
                    className="hidden"
                    multiple
                    onChange={handleFileChange}
                    accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png,.gif"
                  />
                  <div className="flex flex-col items-center">
                    <Upload className="h-12 w-12 text-muted-foreground mb-4" />
                    <h3 className="text-lg font-medium mb-2">
                      Drag files here or click to browse
                    </h3>
                    <p className="text-sm text-muted-foreground mb-4">
                      {uploadType === "incoming"
                        ? "Support for PDF, DOC, DOCX, TXT, JPG, PNG, GIF images files"
                        : "Support for PDF, DOC, DOCX, TXT, JPG, PNG, GIF images files"}
                    </p>
                    <Button>Select Files</Button>
                  </div>
                </div>

                {files.length > 0 && (
                  <>
                    <div className="mt-6">
                      <h3 className="text-lg font-medium mb-4">Upload Queue</h3>
                      <div className="space-y-4">
                        {files.map((file) => (
                          <div
                            key={file.id}
                            className="flex items-center p-3 border rounded-md"
                          >
                            <div className="mr-3">
                              {file.file.type.includes("image") ? (
                                <Image className="h-8 w-8 text-blue-500" />
                              ) : (
                                <FileText className="h-8 w-8 text-blue-500" />
                              )}
                            </div>
                            <div className="flex-1 min-w-0">
                              <p className="text-sm font-medium truncate">
                                {file.name}
                              </p>
                              <div className="flex items-center">
                                <span className="text-xs text-muted-foreground whitespace-nowrap">
                                  {formatFileSize(file.size)}
                                </span>
                              </div>
                            </div>
                            <Button
                              variant="ghost"
                              size="icon"
                              className="ml-2"
                              onClick={() => removeFile(file.id)}
                            >
                              <X className="h-4 w-4" />
                            </Button>
                          </div>
                        ))}
                      </div>
                      <div className="flex justify-between mt-4">
                        <p className="text-sm text-muted-foreground">
                          {files.length} file{files.length !== 1 ? "s" : ""}{" "}
                          selected
                        </p>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => setFiles([])}
                        >
                          <RefreshCw className="h-4 w-4 mr-2" />
                          Clear All
                        </Button>
                      </div>
                    </div>
                    <div className="mt-4 p-3 border rounded-md bg-muted">
                      <p className="text-sm text-muted-foreground">
                        Files will be saved to:{" "}
                        <span className="font-mono text-primary">
                          {pathStructure || "generating-path..."}
                        </span>
                      </p>
                    </div>
                  </>
                )}
              </CardContent>

              <CardContent>
                <div className="flex justify-between mt-4">
                  <div className="space-y-1">
                    <Label htmlFor="ocr">Enable OCR</Label>
                    <p className="text-sm text-muted-foreground">
                      Extract text from documents
                    </p>
                  </div>
                  <Switch
                    id="ocr"
                    checked={ocrEnabled}
                    onCheckedChange={setOcrEnabled}
                  />
                </div>

                <div className="flex justify-between mt-4">
                  <div className="space-y-1">
                    <Label htmlFor="compression">Compress files</Label>
                    <p className="text-sm text-muted-foreground">
                      Reduce file size for storage
                    </p>
                  </div>
                  <Switch
                    id="compression"
                    checked={compressionEnabled}
                    onCheckedChange={setCompressionEnabled}
                  />
                </div>
              </CardContent>

              <CardFooter>
                <Button
                  className="mr-2"
                  onClick={handleUpload}
                  disabled={uploading}
                >
                  {uploading ? "Uploading..." : "Upload"}
                </Button>
                <Button variant="outline">Cancel</Button>
              </CardFooter>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle>Upload Settings</CardTitle>
                <CardDescription>
                  Configure your upload preferences
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="space-y-2">
                  <Label htmlFor="fileType">File Type</Label>
                  <Select
                    value={uploadType}
                    onValueChange={(value: "incoming" | "outgoing") =>
                      setUploadType(value)
                    }
                  >
                    <SelectTrigger id="fileType">
                      <SelectValue placeholder="Select file type" />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectItem value="incoming">Incoming</SelectItem>
                      <SelectItem value="outgoing">Outgoing</SelectItem>
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="organization">Organization</Label>
                  <Select
                    onValueChange={setOrganizationId}
                    value={organizationId || ""}
                  >
                    <SelectTrigger id="organization">
                      <SelectValue placeholder="Select organization" />
                    </SelectTrigger>
                    <SelectContent>
                      {organizations.map((org) => (
                        <SelectItem key={org._id} value={org._id}>
                          {org.name}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="project">Project</Label>
                  <Select
                    onValueChange={setProjectId}
                    value={projectId || ""}
                    disabled={!organizationId}
                  >
                    <SelectTrigger id="project">
                      <SelectValue placeholder="Select project" />
                    </SelectTrigger>
                    <SelectContent>
                      {projects
                        .filter(
                          (project) =>
                            project.organization_id === organizationId
                        )
                        .map((project) => (
                          <SelectItem key={project._id} value={project._id}>
                            {project.name}
                          </SelectItem>
                        ))}
                    </SelectContent>
                  </Select>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="letterNo">Letter Number</Label>
                  <Input
                    type="text"
                    id="letterNo"
                    placeholder="Enter letter number"
                    value={letterNo}
                    onChange={(e) => setLetterNo(e.target.value)}
                  />
                </div>

                <div className="space-y-2">
                  <Label htmlFor="letterDate">Letter Date</Label>
                  <Input
