import React from "react";
import { MemoryRouter } from "react-router-dom";
import { render, RenderOptions } from "@testing-library/react";
import { PartiesProvider } from "@/contexts/PartiesContext.new";

interface TestWrapperProps {
  children: React.ReactNode;
  initialEntries?: string[];
}

interface CustomRenderOptions extends Omit<RenderOptions, "wrapper"> {
  route?: string;
}

export const TestWrapper: React.FC<TestWrapperProps> = ({
  children,
  initialEntries = ["/"],
}) => {
  return (
    <MemoryRouter initialEntries={initialEntries}>
      <PartiesProvider>{children}</PartiesProvider>
    </MemoryRouter>
  );
};

export const renderWithProviders = (
  ui: React.ReactElement,
  options: CustomRenderOptions = {}
) => {
  const { route = "/", ...renderOptions } = options;

  const Wrapper = ({ children }: { children: React.ReactNode }) => (
    <TestWrapper initialEntries={[route]}>{children}</TestWrapper>
  );

  return {
    ...render(ui, { wrapper: Wrapper, ...renderOptions }),
  };
};

// Re-export everything
export * from "@testing-library/react";
export { renderWithProviders as render };

import React from "react";
import { MemoryRouter } from "react-router-dom";
import { PartiesProvider } from "@/contexts/PartiesContext.new";

interface TestWrapperProps {
  children: React.ReactNode;
  initialEntries?: string[];
}

export const TestWrapper: React.FC<TestWrapperProps> = ({
  children,
  initialEntries = ["/"],
}) => {
  return (
    <MemoryRouter initialEntries={initialEntries}>
      <PartiesProvider>{children}</PartiesProvider>
    </MemoryRouter>
  );
};

export const renderWithProviders = (
  ui: React.ReactElement,
  options: { route?: string } = {}
) => {
  const { route = "/" } = options;
  return render(<TestWrapper initialEntries={[route]}>{ui}</TestWrapper>);
};

import React, { ReactElement } from "react";
import {
  render,
  RenderOptions,
  screen,
  waitForElementToBeRemoved,
} from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { PartiesProvider } from "@/contexts/PartiesContext.new";
import { Party, Representative, Concern } from "@/types/api";

interface CustomRenderOptions extends Omit<RenderOptions, "wrapper"> {
  initialParties?: Party[];
  initialConcerns?: Concern[];
}

// Create a custom render function that includes providers
const customRender = (ui: ReactElement, options?: CustomRenderOptions) => {
  const AllProviders = ({ children }: { children: React.ReactNode }) => {
    return <PartiesProvider>{children}</PartiesProvider>;
  };

  return render(ui, { wrapper: AllProviders, ...options });
};

// Re-export everything
